function renderFeedback(data){if(!Array.isArray(data?.feedback))throw Error('反馈记录响应不完整，请重试。');const rows=data.feedback;$('#page').innerHTML=heading('反馈与处理记录','在任一对话中发送“反馈：”并说明问题，保存回执与后续处理会记录在这里。',iconButton('刷新反馈记录','refresh','data-action="refresh"'),'FEEDBACK / 反馈记录')+`<section class="stack">${rows.map(row=>`<article class="card" data-feedback-id="${e(row.id)}"><div class="section-heading"><h2>反馈 ${e(String(row.id).slice(0,8))}</h2>${supportStatusHTML(row.status,'feedback')}</div><p class="form-help">记录于 ${e(timeString(row.created_at))} · 更新于 ${e(timeString(row.updated_at))}</p>${row.status==='deleted'?'<p>此反馈已删除。</p>':`<div class="markdown-body">${renderMarkdown(row.body||'')}</div>${row.resolution?`<details data-support-detail="feedback-${e(row.id)}"><summary>${row.status==='resolved'?'处理结果':'处理说明'}</summary><div class="markdown-body">${renderMarkdown(row.resolution)}</div>${Array.isArray(row.evidence)&&row.evidence.length?`<p class="form-help">处理依据</p><ul>${row.evidence.map(item=>`<li class="summary-text">${e(item)}</li>`).join('')}</ul>`:''}</details>`:Array.isArray(row.evidence)&&row.evidence.length?`<details data-support-detail="feedback-${e(row.id)}"><summary>处理依据</summary><ul>${row.evidence.map(item=>`<li class="summary-text">${e(item)}</li>`).join('')}</ul></details>`:''}<div class="flex">${row.activity_id?`<a class="quiet-link" href="#activity/${encodeURIComponent(row.activity_id)}">${icon('chat')}回到原对话</a>`:''}${row.message_id?`<button class="small ghost" data-action="source-open" data-ref="message:${e(row.message_id)}">查看反馈原话</button>`:''}</div>`}</article>`).join('')||`<article class="card">${empty('还没有反馈记录。','直接在对话中发送“反馈：具体问题”，即可留下可追溯记录。','feedback')}</article>`}</section><p class="form-help">“已完成”以处理结果记录为准；收到反馈不表示代码已经修改或部署。</p>`;}
function renderStudy(data){if(!Array.isArray(data?.sources)||!Array.isArray(data?.notes)||!data.policy||!data.status)throw Error('研读进度响应不完整，请重试。');const {policy,sources,notes,status}=data;$('#page').innerHTML=heading('夜间研读','查看实际取得的材料、研读笔记和待补充来源。',iconButton('刷新研读进度','refresh','data-action="refresh"'),'STUDY / 夜间研读')+`<div class="stack"><section class="card"><div class="section-heading"><h2>${policy.enabled===true?'夜间研读已开启':policy.enabled===false?'夜间研读已暂停':'研读安排待核对'}</h2><span class="tag">${e(policy.timezone||'时区未报告')}</span></div><dl class="summary-list"><div class="summary-entry"><dt>研读时段</dt><dd>${e(policy.window_start||'未报告')}—${e(policy.window_end||'未报告')}</dd></div><div class="summary-entry"><dt>最近运行</dt><dd>${status.last_run?e(typeof status.last_run==='string'?timeString(status.last_run):readable(status.last_run)):'尚无运行记录'}</dd></div><div class="summary-entry"><dt>下次时段</dt><dd>${status.next_window?e(typeof status.next_window==='string'?timeString(status.next_window):readable(status.next_window)):'尚未排定'}</dd></div><div class="summary-entry"><dt>已保存笔记</dt><dd>${e(Number.isInteger(status.total_notes)?status.total_notes:'未报告')}</dd></div></dl></section><section class="card"><div class="section-heading"><h2>资料与进度</h2><span class="muted small">${sources.length} 项</span></div><div class="row-list">${sources.map(source=>`<article class="list-row" data-study-source="${e(source.id)}"><div><h3>${e(source.title||'未命名资料')}</h3><p>${e([source.author,source.kind].filter(Boolean).join(' · '))}</p>${supportStatusHTML(source.status,'study')}${source.reason?`<p class="summary-text">${e(source.reason)}</p>`:''}${supportSourceLink(source.url,'来源页面')}</div></article>`).join('')||empty('尚未登记研读来源。')}</div><p class="form-help">只有已保存的研读笔记才列为进展；资料书目、网页链接与等待取得的正文分别标记。</p></section><section class="card"><div class="section-heading"><h2>研读笔记</h2><span class="muted small">本页 ${notes.length} 篇</span></div><div class="stack">${notes.map(note=>`<details data-support-detail="study-${e(note.id)}" data-study-note="${e(note.id)}"><summary>${e(note.title||'研读笔记')} · ${e(timeString(note.created_at))}</summary><div class="markdown-body">${renderMarkdown(note.summary||'')}</div>${supportSourceLink(note.source_url,'查看笔记来源')}</details>`).join('')||empty('还没有研读笔记。','取得正文并完成研读后，实际结果会出现在这里。','study')}</div></section></div>`;}
function renderSupportPage(kind,data,preserve=false){const area=$('#page'),opened=preserve?$$('details[open][data-support-detail]',area).map(el=>el.dataset.supportDetail):[],scroll=preserve?area.scrollTop:0;if(kind==='feedback')renderFeedback(data);else renderStudy(data);supportViewData={kind,data};for(const detail of $$('details[data-support-detail]',area))detail.open=opened.includes(detail.dataset.supportDetail);area.scrollTop=scroll;}
async function updateSupportPage(){const kind=route,generation=loadGeneration,readGeneration=++supportReadGeneration;if(!['feedback','study'].includes(kind))return;const data=await api('/api/'+kind);if(route!==kind||loadGeneration!==generation||supportReadGeneration!==readGeneration||!$('#page'))return;if(supportViewData?.kind!==kind||!sameData(supportViewData.data,data))renderSupportPage(kind,data,true);}
function taskVersion(t){return t.current_version||t.version||t.deliveries?.at(-1)?.version||0;}
function taskRequirementsHTML(task){
  const labels={goal:'目标',inputs:'输入材料',deliverable:'交付内容',acceptance:'验收条件'},version=Number.isInteger(task.requirements_version)?task.requirements_version:0;
  const fields=values=>`<dl class="summary-list">${Object.entries(labels).map(([key,label])=>`<div class="summary-entry"><dt>${label}</dt><dd>${e(values?.[key]||'未填写')}</dd></div>`).join('')}</dl>`;
  return `<details data-task-requirements><summary>当前需求 · 版本 ${e(version)}</summary>${fields(task)}<p class="subtle">需求版本独立于成果版本；修改要求不会覆盖旧成果或此前验收。</p>${(task.requirements_history||[]).length?`<details data-requirements-history><summary>查看需求修订记录（${task.requirements_history.length}）</summary>${task.requirements_history.map(item=>{const before=parseObject(item.before_json)||{},after=parseObject(item.after_json)||{},changed=Object.keys(labels).filter(key=>typeof after[key]==='string'&&after[key]!==before[key]);return `<details data-requirements-revision="${e(item.requirements_version)}"><summary>需求版本 ${e(item.requirements_version)} · ${e(timeString(item.created_at))}</summary>${changed.length?`<dl class="summary-list">${changed.map(key=>`<div class="summary-entry"><dt>${labels[key]} · 修订前</dt><dd>${e(before[key]||'未填写')}</dd><dt>${labels[key]} · 修订后</dt><dd>${e(after[key]||'未填写')}</dd></div>`).join('')}</dl>`:'<p class="subtle">此修订的内容已清理，保留版本记录。</p>'}${item.user_input?`<p>原始要求：${e(item.user_input)}</p>`:''}${item.source_message_id?sourceHTML('message:'+item.source_message_id):''}</details>`;}).join('')}</details>`:'<p class="subtle">尚无需求修订记录。</p>'}</details>`;
}
function renderTasks(){const tasks=state.tasks||[];$('#page').innerHTML=`${heading('把委托交给执行，把判断留给自己。','任务在服务端持续执行。成果提交后，由你验收具体版本。',`<button class="primary" data-action="task-new">＋ 新建委托</button>`,'TASKS / 委托任务')}<div class="task-grid">${tasks.map(t=>{const version=taskVersion(t),delivery=(t.deliveries||[]).filter(item=>item.body).at(-1),result=delivery?.body||t.result,resultVersion=delivery?.version??version;return `<article class="card task-card" data-task-id="${e(t.id)}"><div class="card-top">${tag(t.status)}<span class="muted small">需求版本 ${e(Number.isInteger(t.requirements_version)?t.requirements_version:0)}</span></div><h3>${e(t.goal||t.title)}</h3><p>${e(t.deliverable||t.inputs||'')}</p><div class="subtle">${e(t.owner==='user'?'由我行动':['shared','共同'].includes(t.owner)?'共同完成':'Agent 执行')} · ${t.run_at?e(timeString(t.run_at)):'立即执行'}${t.interval_days?' · 每 '+e(t.interval_days)+' 天':''}</div>${t.error?`<div class="notice error" data-layout="layout-9">${e(t.error)}</div>`:''}${taskRequirementsHTML(t)}<details data-task-delivery ${['awaiting_acceptance','submitted'].includes(t.status)?'open':''}><summary>成果与版本验收</summary>${result?`<p>成果版本 ${e(resultVersion)}</p>${t.status==='revision'||(t.status==='running'&&resultVersion!==version)?'<p class="subtle">此前成果仍保留；新一轮尚未交付，旧验收仍属于原成果版本。</p>':''}<div class="task-result">${e(readable(result))}</div>`:'<p class="subtle">尚未提交成果。</p>'}${(t.deliveries||[]).filter(item=>item.body).length>1?`<p class="subtle">保留 ${(t.deliveries||[]).filter(item=>item.body).length} 个成果版本。</p>`:''}</details><div class="flex">${['awaiting_acceptance','submitted'].includes(t.status)?`<button class="primary small" data-action="task-review" data-id="${e(t.id)}" data-version="${e(version)}" data-review="accept">验收此版本</button><button class="small" data-action="task-review" data-id="${e(t.id)}" data-version="${e(version)}" data-review="revise">要求返修</button>`:''}${!['cancelled','running'].includes(t.status)?`<button class="small ghost" data-action="task-run" data-id="${e(t.id)}">立即执行</button>`:''}${t.status!=='cancelled'?`<button class="small ghost" data-action="task-review" data-id="${e(t.id)}" data-version="${e(version)}" data-review="cancel">取消${t.interval_days?'后续周期':''}</button>`:''}${t.source_activity_id?`<a class="small" href="#activity/${encodeURIComponent(t.source_activity_id)}">来源活动 →</a>`:''}</div></article>`}).join('')}</div>${!tasks.length?`<section class="card">${empty('还没有明确委托。','一句想法不会自动成为任务。明确目标后，即可建卡执行。','task')}</section>`:''}`;}

function growthItems(key){const g=state.growth||[];if(Array.isArray(g)){const grouped=g.find(x=>x.line===key&&Array.isArray(x.items));return grouped?grouped.items:g.filter(x=>x.line===key);}return Array.isArray(g.items)?g.items.filter(x=>x.line===key):g[key]?.items||g[key]||[];}
function sourceHTML(refs){return (Array.isArray(refs)?refs:refs?[refs]:[]).map(ref=>{if(String(ref).startsWith('attachment:')){const id=String(ref).slice(11);return id.trim()?`<a class="small" href="/api/attachment?id=${e(encodeURIComponent(id))}" download>下载来源附件</a>`:'<span class="small subtle">附件引用缺少编号</span>';}let url='';if(String(ref).startsWith('activity:'))url='#activity/'+encodeURIComponent(String(ref).slice(9));else if(/^https?:\/\//i.test(ref))url=String(ref);else if(String(ref).startsWith('#activity/'))url=ref;return url?`<a class="small" href="${e(url)}" ${url.startsWith('http')?'target="_blank" rel="noopener noreferrer"':''}>${e(ref)}</a>`:`<button class="small ghost" data-action="source-open" data-ref="${e(ref)}">${e(ref)} ↗</button>`;}).join('<br>');}
function renderGrowth(){const items=growthItems(line);const groups=[['goal','目标与当前状态',['goal','current_state']],['capability','能力与证据',['capability']],['plan','90 天阶段计划',['plan','revision']],['action','当日行动与委托',['action']],['outcome','成果与用户评价',['outcome','evaluation']],['review','周回顾与下一次调整',['review']]];$('#page').innerHTML=`${heading('让成长的判断，有真实的依据。','目标、证据、行动和复盘持续关联。你可以随时修订阶段安排。',`<button class="primary" data-action="growth-new">＋ 添加记录</button>`,'GROWTH / 三条主线')}<div class="growth-tabs">${Object.entries(lineNames).map(([key,name])=>`<button data-action="growth-line" data-line="${key}" class="${line===key?'active':''}">${name}</button>`).join('')}</div><div class="notice info">${lineNames[line]} · ${items.some(x=>x.kind==='current_state'&&x.user_input)?'已有用户核对的当前状态':'当前状态待你核对，不从记录缺失推断投入或能力'}。阶段计划与行动记录不会自动授权批量执行。</div><div class="growth-columns">${groups.map(([key,title,kinds])=>`<section class="card"><div class="section-heading"><h2>${title}</h2><button class="small ghost" data-action="growth-new" data-kind="${key}">＋ 添加</button></div>${items.filter(x=>kinds.includes(x.kind)&&x.active!==false).map(x=>`<article class="growth-item"><span class="tag">${e(kindNames[x.kind]||x.kind)}</span><p data-layout="layout-2">${e(growthText(x.content))}</p>${sourceDateHTML(x.content,x.business_date)}<div class="meta">版本 ${e(x.version||1)} · ${e(timeString(x.updated_at||x.created_at))}${x.user_input?' · 用户已提交':' · 未核对'}${(x.review_date||x.content?.review_date)?' · 复盘 '+e(x.review_date||x.content?.review_date):''}</div>${sourceHTML(x.source_refs||x.source_ref)}<div class="flex" data-layout="layout-2"><button class="small ghost" data-action="growth-edit" data-id="${e(x.item_id||x.id)}">修订</button>${x.kind==='outcome'?`<button class="small ghost" data-action="growth-evaluate" data-id="${e(x.item_id||x.id)}">记录我的评价</button>`:''}</div></article>`).join('')||empty('还没有这类记录','添加实际材料，保留出处。','leaf')}</section>`).join('')}</div>${weeklyHTML()}`;}
function weeklyHTML(){const w=state.weekly_review;if(!w)return '';const items=w.lines?.[line]||[];const period=weekOffset===0?'本周':'上一完整周';return `<section class="card" data-layout="layout-15"><div class="section-heading"><h2>${e(w.label||'周回顾')}</h2><span class="muted small">${e(w.start)} — ${e(w.end)}</span></div><div class="growth-tabs" aria-label="周回顾时段"><button data-action="growth-week" data-offset="0" class="${weekOffset===0?'active':''}" aria-pressed="${weekOffset===0}">本周</button><button data-action="growth-week" data-offset="-7" class="${weekOffset===-7?'active':''}" aria-pressed="${weekOffset===-7}">上一完整周</button></div><p class="subtle">截至 ${e(timeString(w.as_of))} · ${lineNames[line]}</p>${items.length?items.map(x=>`<div class="growth-item"><span class="tag">${e(kindNames[x.kind]||x.kind)}</span><p>${e(growthText(x.content))}</p>${sourceHTML(x.source_refs||[])}</div>`).join(''):empty(period+'尚无这条主线的成长记录。','记录缺失不代表未投入，也不构成能力下降判断。')}<button class="small ghost" data-action="growth-new" data-kind="review" data-date="${e(weekOffset===0?(state.today||today()):w.end)}">＋ 补充${period}评价与拟调整事项</button></section>`;}
function materialOverviewHTML(items){const rows=items.filter(p=>p.active!==false&&p.scope==='reference:personal-history');if(!rows.length)return '';return `<section class="card material-overview"><div class="section-heading"><h2>资料综述</h2><span class="tag">${rows.length} 个主题</span></div><p class="subtle">将散落的经历与线索按主题整理。原话、平台记忆与参考稿保留各自出处；历史计划不代表当前状态，日期不详处保留未知。</p>${rows.map(p=>`<article class="profile" data-material-overview="${e(p.item_id)}"><div class="markdown-body">${renderMarkdown(p.content)}</div><div class="meta">来源综述 · 版本 ${e(p.version||1)}</div><details><summary>查看依据与来源</summary>${sourceHTML(p.source_refs||[])}</details><div class="flex"><button class="small ghost" data-action="profile-edit" data-id="${e(p.item_id)}">更正综述</button><button class="small ghost" data-action="profile-disable" data-id="${e(p.item_id)}">收起此综述</button></div></article>`).join('')}</section>`;}
function renderData(){const profiles=state.profiles||[],imports=state.imports||[];$('#page').innerHTML=`${heading('把散落的资料，带回同一个地方。','历史会话、个人记忆与项目规则分别归档，来源始终可查。','','LIBRARY / 资料与画像')}<div data-deletion-pending="">${deletionPendingHTML()}</div>${materialGuidesHTML()}${materialOverviewHTML(profiles)}<div class="two-col"><section class="card"><div class="section-heading"><h2>导入历史资料</h2><span class="tag">先预览，再导入</span></div><form id="import-form"><div class="two-col"><div><label for="import-source">来源</label><select id="import-source" name="source"><option value="kimi">Kimi</option><option value="codex">Codex</option><option value="chatgpt">ChatGPT</option></select></div><div><label for="import-kind">资料类型</label><select id="import-kind" name="kind"><option value="conversation">历史会话</option><option value="memory">手动 Memory</option><option value="instructions">AGENTS / 项目规则</option></select></div></div><label for="import-scope">作用域</label><input id="import-scope" name="scope" value="imported" placeholder="例如 imported 或 project:研究项目"><p class="form-help">项目规则请填写 project:项目名。导入文本中的指令不会自动执行。</p><div class="file-drop" data-layout="layout-10"><p>选择 JSON、JSONL 或 Markdown 原文件</p><input type="file" id="import-file" accept=".json,.jsonl,.md,.txt" required aria-label="选择历史资料文件"></div><div class="form-actions"><button class="primary" type="submit">预览导入</button></div></form><div id="import-preview" aria-live="polite"></div></section><section class="card"><div class="section-heading"><h2>个人画像与有效偏好</h2><button class="small ghost" data-action="profile-new">＋ 添加</button></div>${profiles.filter(p=>p.active!==false&&p.scope!=='reference:personal-history').map(p=>`<article class="profile"><p>${e(p.content)}</p><div class="meta">${e(p.scope||'未指定作用域')} · ${p.evidence_status==='source_attested'?'来源明确·已生效':p.confirmed?'本人已确认':'不作为当前推定'} · 版本 ${e(p.version||1)}</div>${sourceHTML(p.source_refs||p.source_ref)}<div class="flex" data-layout="layout-11"><button class="small ghost" data-action="profile-edit" data-id="${e(p.item_id||p.id)}">更正</button><button class="small ghost" data-action="profile-disable" data-id="${e(p.item_id||p.id)}">停用此记忆</button></div></article>`).join('')||empty('只保留有出处、可更正的认识。','导入资料不会自动升级为全局偏好。','data')}</section></div><section class="card" data-layout="layout-12"><div class="section-heading"><h2>导入批次</h2><a class="small" href="/api/export">完整导出 →</a></div>${imports.map(b=>`<div class="list-row"><div><h4>${e(b.filename||b.channel||b.source)}</h4><p>${e(timeString(b.imported_at||b.created_at))} · ${e(b.count||b.counts?.new||b.report?.counts?.new||0)} 条新增 · ${e(b.scope||'')}${b.status==='removed'?' · 本批新增记录已移除':''}</p></div><button class="small danger" data-action="import-remove" data-id="${e(b.batch_id||b.id)}">${b.status==='removed'?'核对清理状态':'移除此批新增'}</button></div>`).join('')||empty('尚无导入批次。','重复导入会核对指纹；移除批次不会误删此前存在的记录。','data')}</section>`;}
function bytes(x){if(x===undefined||x===null)return '未报告';if(x<1024)return x+' B';if(x<1024**2)return (x/1024).toFixed(1)+' KB';if(x<1024**3)return (x/1024**2).toFixed(1)+' MB';return (x/1024**3).toFixed(2)+' GB';}
function renderSettings(){const health=state.health||{},b={...(state.budget||{})};if(Array.isArray(b.usage)){const rows=b.usage.filter(x=>x.kind==='background');b.daily_used=rows.filter(x=>x.day===(b.today||today())).reduce((n,x)=>n+Number(x.settled||0),0);b.daily_reserved=rows.filter(x=>x.day===(b.today||today())).reduce((n,x)=>n+Number(x.reserved||0),0);b.monthly_used=rows.filter(x=>x.month===(b.today||today()).slice(0,7)).reduce((n,x)=>n+Number(x.settled||0),0);b.monthly_reserved=rows.filter(x=>x.month===(b.today||today()).slice(0,7)).reduce((n,x)=>n+Number(x.reserved||0),0);}$('#page').innerHTML=`<div class="settings-account">${iconButton('更改密码','lock','data-action="password-change"')}</div>${chronicleSettingsHTML()}${heading('按你的节奏，稳定地运行。','日程只因你的明确操作改变。沉默、短答和单次跳过不会自动降频。','','SETTINGS / 设置与运行')}<div data-deletion-pending="">${deletionPendingHTML()}</div><div class="toolbar"><a href="#data">资料导入与画像 →</a><a href="#learning">学习收藏 →</a><span class="spacer"></span><button class="small" data-action="logout">退出登录</button></div>${routineSettingsHTML()}<div class="two-col" data-layout="layout-12"><section class="card"><div class="section-heading"><h2>运行与待处理状态</h2><button class="small ghost" data-action="retry-all">重试失败步骤</button></div><div class="status-grid">${[['模型',health.model||health.model_state||'未报告'],['通知',health.notification||health.notification_state||'仅页面可见'],['待处理',health.pending??health.pending_count??'未报告'],['最近成功',health.last_success?timeString(health.last_success):'尚无记录'],['备份',health.backup||health.backup_state||'未报告'],['数据容量',bytes(health.storage_bytes)]].map(([k,v])=>`<div class="status-box"><h4>${e(k)}</h4><pre>${e(readable(v))}</pre></div>`).join('')}</div>${health.model_error?`<div class="notice error" data-layout="layout-13">${e(health.model_error)}</div>`:''}<p class="form-help">通道接受、设备送达和已读分别记录；未连接外部通道时只能在页面查看。</p></section><section class="card"><h2>${b.background_limit_enforced===false?'后台用量记录（未设本地限额）':'预算与数据维护'}</h2><div data-layout="layout-14"><div class="flex spread small"><span>今日后台用量 / 预留</span><strong>${e(b.daily_used??b.used_today??0)} / ${e(b.daily_reserved??b.reserved??0)}</strong></div>${b.background_limit_enforced===false?'<p class="form-help">本地每日及每月限额已解除，继续记录已结算用量与预留。</p>':`<progress class="budget-progress" aria-label="今日后台预算使用与预留" max="${e(b.daily_limit||60000)}" value="${e(Number(b.daily_used||0)+Number(b.daily_reserved||0))}"></progress><p class="form-help">每日额度 ${e(b.daily_limit||60000)} token · 月额度 ${e(b.monthly_limit||1000000)} token</p>`}<p class="form-help">本月使用 ${e(b.monthly_used??0)} · 预留 ${e(b.monthly_reserved??0)}</p></div><p class="subtle">${b.background_limit_enforced===false?'服务商额度、并发与模型配置仍可能影响处理；原话持续保存，每日安排不变。':'预算不足时仍保存原话；模型处理等待额度或配置恢复，不改变每日安排。'}</p><div class="flex" data-layout="layout-15"><a class="pill-link small" href="/api/export">${icon('export')} 完整导出</a><a class="small" href="/api/export?format=markdown">可读 Markdown</a></div><button class="small" data-layout="layout-10" data-action="cleanup">清理可再生缓存</button><p class="form-help">清理不删除唯一原文、待答问题或有效附件。</p></section></div><section class="card" data-layout="layout-12"><h2>版本与真实运行观察</h2><dl class="summary-list"><div class="summary-entry"><dt>当前版本</dt><dd>${e(health.version||'未报告')}</dd></div><div class="summary-entry"><dt>观察记录</dt><dd>${e(readable(health.observation||'由服务端持续记录；尚无完整七日观察结论。'))}</dd></div></dl><p class="subtle">真实手机、异机备份和七日运行需要各自的实际证据，界面可打开不代表这些项目已经通过。</p></section>`;}
function openModal(title,body){$('#modal-content').innerHTML=`<div class="modal-head"><h2>${e(title)}</h2><button class="icon ghost" data-action="modal-close" aria-label="关闭">${icon('close')}</button></div>${body}`;$('#modal').showModal();}
function closeModal(){$('#modal').close();}
function formActions(label='保存'){return `<div class="form-actions"><button type="button" data-action="modal-close">取消</button><button type="submit" class="primary">${e(label)}</button></div>`;}
function taskModal(){openModal('新建明确委托',`<form id="task-form"><input type="hidden" name="submission_id" value="${e(uid())}"><label for="task-goal">希望完成什么</label><textarea id="task-goal" name="goal" placeholder="写清目标、范围和期望结果" required></textarea><div class="two-col"><div><label for="task-owner">由谁完成</label><select id="task-owner" name="owner"><option value="agent">Agent 执行</option><option value="user">我本人行动</option><option value="共同">共同完成</option></select></div><div><label for="task-time">开始时间（上海时间）</label><input id="task-time" name="run_at" type="datetime-local"><p class="form-help">留空表示现在执行。</p></div></div><label for="task-inputs">必要输入</label><textarea id="task-inputs" name="inputs" placeholder="可用资料、文件定位、明确的权限范围" data-layout="layout-16"></textarea><label for="task-delivery">期望交付物</label><input id="task-delivery" name="deliverable" placeholder="例如：带来源的整理文档"><label for="task-acceptance">验收条件</label><input id="task-acceptance" name="acceptance" placeholder="你会根据什么判断这份成果是否完成"><label for="task-repeat">周期执行</label><select id="task-repeat" name="interval_days"><option value="0">一次性</option><option value="1">每天</option><option value="7">每 7 天</option><option value="30">每 30 天</option></select><p class="form-help">点击创建后进入执行或排期。任务成果仍需你验收；本人行动不会被自动标记完成。</p><input type="hidden" name="source_activity_id" value="${e(route==='activity'?routeId:'')}">${formActions('创建并执行 / 排期')}</form>`);}
function reviewModal(id,version,mode){const labels={accept:'验收此版本',revise:'要求返修',cancel:'取消委托 / 后续周期'};openModal(labels[mode],`<form id="review-form"><input type="hidden" name="task_id" value="${e(id)}"><input type="hidden" name="version" value="${e(version)}"><input type="hidden" name="action" value="${e(mode)}"><p class="subtle">本次操作明确绑定成果版本 <strong>${e(version)}</strong>。返修后的新版本会重新等待验收。</p><label for="review-input">${mode==='accept'?'你的验收意见':mode==='revise'?'需要调整的具体内容':'取消说明'}</label><textarea id="review-input" name="input" required>${mode==='accept'?'这版验收通过。':''}</textarea>${formActions(labels[mode])}</form>`);}

const learningCategoryNames={classic:'经典古籍',history:'中国史与党史',modern:'现代概念'};
function routineSettingsHTML(){
 return `<section class="card routine-settings-card"><div class="section-heading"><h2>日常内容与打卡时间</h2><span class="muted small">北京时间</span></div><div class="row-list">${['A1','A2','A3'].map(r=>{
  const schedule=(state.schedules||[]).find(x=>x.routine===r)||{time:routineInfo[r].time,weekdays:[0,1,2,3,4,5,6]},saved=state.routine_settings?.[r],settings=saved?.settings||{};
  const summary=r==='A1'?Object.entries(learningCategoryNames).map(([key,label])=>`${label}：${settings.topics?.[key]||'持续扩充'}`).join(' · '):r==='A2'?(settings.dimensions||[]).map(x=>x.label).join('、'):'记录睡眠，也可继续聊聊身心状态。';
  return `<div class="list-row routine-settings-row" data-routine-settings="${r}"><div class="row-start"><span class="routine-icon ${r}">${icon(routineInfo[r].icon)}</span><div><h3>${routineInfo[r].name}</h3><p class="routine-settings-summary">${e(summary)}</p><p>${e(schedule.time)} · ${schedule.weekdays?.length===7?'每天':(schedule.weekdays||[]).map(x=>'周'+'一二三四五六日'[x]).join('、')}${schedule.paused_until?' · 暂停至 '+e(schedule.paused_until):''}</p><p>下一次：${e(timeString(schedule.next_at))}${schedule.next_at?'（北京时间）':''}${saved?' · 内容版本 '+e(saved.version):''}</p></div></div><div class="routine-settings-actions">${r!=='A3'?`<button class="small" data-action="routine-settings-edit" data-routine="${r}">${icon('edit')}${r==='A1'?'内容要求':'反思方面'}</button>`:''}<button class="small" data-action="schedule-edit" data-routine="${r}">${icon('history')}打卡时间</button></div></div>`;
 }).join('')}</div><p class="form-help">内容、时间分别保存。暂停结束后恢复原安排，历史日期仍可补填。</p></section>`;
}
function routineDimensionRow(item={}){
 const key=uid();
 return `<fieldset class="routine-dimension" data-dimension-id="${e(item.id||'')}"><legend>反思方面</legend><div class="routine-dimension-top"><label class="sr-only" for="dimension-label-${key}">方面名称</label><input id="dimension-label-${key}" data-field="label" value="${e(item.label||'')}" maxlength="80" placeholder="例如：科研进展、身体状态" aria-label="方面名称" required><button type="button" class="icon-button ghost" data-action="routine-dimension-remove" aria-label="移除此方面" title="移除此方面">${icon('trash')}</button></div><label for="dimension-prompt-${key}">希望怎样回顾（可选）</label><textarea id="dimension-prompt-${key}" data-field="prompt" maxlength="1000" rows="2" placeholder="例如：回看具体进展、困难和下一步">${e(item.prompt||'')}</textarea><details class="routine-keywords"><summary>匹配关键词</summary><label class="sr-only" for="dimension-keywords-${key}">匹配关键词</label><input id="dimension-keywords-${key}" data-field="keywords" value="${e((item.keywords||[]).join('、'))}" placeholder="用顿号分隔；留空使用方面名称" aria-label="匹配关键词"></details></fieldset>`;
}
function routineSettingsModal(r){
 const saved=state.routine_settings?.[r];if(!saved)throw Error('暂未读到内容设置，请刷新后重试。');
 const settings=saved.settings||{};
 const content=r==='A1'?`${Object.entries(learningCategoryNames).map(([key,label])=>`<label for="learning-topic-${key}">${label} · 近期主题</label><input id="learning-topic-${key}" name="topic_${key}" value="${e(settings.topics?.[key]||'')}" list="learning-sources-${key}" maxlength="160" placeholder="留空：按原方向持续扩充"><datalist id="learning-sources-${key}">${(state.learning_source_options||[]).filter(x=>x.category===key).map(x=>`<option value="${e(x.title||x.source_title||'')}"></option>`).join('')}</datalist>`).join('')}<p class="form-help">可填写主题关键词，或选择已有材料。暂缺匹配材料时会保留主题并显示缺口；留空的部分继续按原方向选材。</p><label for="learning-teaching-request">授课要求</label><textarea id="learning-teaching-request" name="teaching_request" maxlength="4000" rows="4" placeholder="例如：先解读原文，再用一个具体问题检验理解">${e(settings.teaching_request||'')}</textarea>`:`<p class="subtle">依次写下你关心的方面与回顾重点。新活动采用保存后的设置，已开始的反思保留当时的方面。</p><div id="routine-dimensions">${(settings.dimensions||[]).map(routineDimensionRow).join('')}</div><button type="button" class="small" data-action="routine-dimension-add">${icon('plus')}添加一个方面</button><p class="form-help">可设置 1—12 个方面。</p>`;
 openModal(r==='A1'?'每日一学 · 内容要求':'每日反思 · 自定义方面',`<form id="routine-settings-form"><input type="hidden" name="routine" value="${r}"><input type="hidden" name="expected_version" value="${e(saved.version)}"><input type="hidden" name="submission_id" value="${e(uid())}">${content}<p class="form-help">当前版本 ${e(saved.version)}。保存后会显示实际变更回执。</p>${formActions('保存'+(r==='A1'?'学习要求':'反思方面'))}</form>`);
}
function reflectionDimensionsHTML(data){
 const dimensions=data.reflection_dimensions||[];if(!dimensions.length)return '';
 return `<div class="reflection-dimensions"><h4>本次反思方面</h4>${dimensions.map(item=>{const step=(data.reflection||[]).find(x=>x.line===item.id);return `<p><span>${e(item.label)}</span>${tag(step?.state==='answered'?'已聊':step?.state||'待聊')}</p>`;}).join('')}</div>`;
}
async function saveRoutineSettings(form){
 const fd=new FormData(form),routine=String(fd.get('routine')),settings=routine==='A1'?{topics:Object.fromEntries(Object.keys(learningCategoryNames).map(key=>[key,String(fd.get('topic_'+key)||'').trim()])),teaching_request:String(fd.get('teaching_request')||'').trim()}:{dimensions:$$('.routine-dimension',form).map(row=>({...(row.dataset.dimensionId?{id:row.dataset.dimensionId}:{}),label:$('[data-field="label"]',row).value.trim(),prompt:$('[data-field="prompt"]',row).value.trim(),keywords:$('[data-field="keywords"]',row).value.split(/[,，、\n]/).map(x=>x.trim()).filter(Boolean)}))};
 if(routine==='A2'&&(!settings.dimensions.length||settings.dimensions.length>12))throw Error('请保留 1—12 个反思方面。');
 const payload={routine,expected_version:Number(fd.get('expected_version')),settings},signature=JSON.stringify(payload);
 if(form.dataset.submittedPayload&&form.dataset.submittedPayload!==signature)form.elements.submission_id.value=uid();
 form.dataset.submittedPayload=signature;
 const result=await action('routine_settings',{...payload,submission_id:form.elements.submission_id.value});
 state.routine_settings={...(state.routine_settings||{}),[routine]:result};
 closeModal();await loadRoute();
 openModal('设置变更回执',`<section class="routine-settings-receipt" role="status"><p><strong>${e(routineInfo[routine].name)} · 版本 ${e(result.version)}</strong></p><div class="markdown-body">${renderMarkdown(result.message||'设置已保存。')}</div>${result.effective?`<p class="subtle">${e(result.effective)}</p>`:''}${result.missing_topics?.length?`<div class="notice"><strong>待补材料</strong><ul>${result.missing_topics.map(item=>`<li>${e(learningCategoryNames[item.category]||item.category)}：${e(item.topic)}</li>`).join('')}</ul></div>`:''}${result.receipt?`<details><summary>回执编号</summary><p class="code-text">${e(typeof result.receipt==='string'?result.receipt:result.receipt.id||readable(result.receipt))}</p></details>`:''}<div class="form-actions"><button type="button" class="primary" data-action="modal-close">知道了</button></div></section>`);
}

function scheduleModal(r){const s=(state.schedules||[]).find(x=>x.routine===r)||{time:routineInfo[r].time,weekdays:[0,1,2,3,4,5,6]};openModal(`调整${routineInfo[r].name}`,`<form id="schedule-form"><input type="hidden" name="routine" value="${r}"><input type="hidden" name="submission_id" value="${e(uid())}"><input type="hidden" name="expected_updated_at" value="${e(s.updated_at||'')}"><label for="schedule-time">打卡时间（北京时间）</label><input id="schedule-time" name="time" type="time" value="${e(s.time)}" required><label>在哪些日子触发</label><div class="weekdays">${Array.from({length:7},(_,i)=>`<label><input name="weekdays" type="checkbox" value="${i}" ${s.weekdays?.includes(i)?'checked':''}>周${'一二三四五六日'[i]}</label>`).join('')}</div><button type="button" class="ghost small" data-action="schedule-daily">恢复每天</button><label for="schedule-pause">暂停到指定日期（可选）</label><input id="schedule-pause" name="paused_until" type="date" min="${state.today||today()}" value="${e(s.paused_until?.slice(0,10)||'')}"><p class="form-help">暂停包含所选日期，次日恢复原安排。清空暂停日期表示取消暂停。这里只调整${routineInfo[r].name}，其他例程不受影响。</p>${r==='A1'?'<p class="form-help">学习材料提前准备，通过检查后到此时间发布。</p>':''}<p class="form-help">活动按所选时间就绪；外部通知仍遵循 23:00—08:00 免打扰，期间可直接打开网页查看。</p>${formActions('保存打卡时间')}</form>`);}
function correctionModal(){const a=currentActivity.activity;const rawSummary=parseObject(currentActivity.summary)||{};const s=rawSummary.fields||rawSummary;const keys=a.routine==='A3'?['sleep_time','wake_time','quality','exercise_actual','exercise_plan','mood']:['progress','insights','constraints','decisions','next_steps','assistance'];openModal('更正当前记录',`<form id="correction-form"><p class="subtle">更正会持续作用于后续摘要，原话仍保留其出处。只提交你实际修改的字段；清空字段表示明确撤回这个值。</p>${keys.map(k=>`<label for="correction-${k}">${fieldsCN[k]}</label><textarea id="correction-${k}" name="${k}" data-original="${e(s[k]===undefined||s[k]===null?'':readable(s[k]))}" data-layout="layout-17">${e(s[k]===undefined||s[k]===null?'':readable(s[k]))}</textarea>`).join('')}<label for="correction-source">更正说明（可选）</label><input id="correction-source" name="source" placeholder="例如：上一条说错了，实际是…">${formActions('保存更正')}</form>`);}
function profileModal(id){const p=(state.profiles||[]).find(x=>(x.item_id||x.id)===id)||{};openModal(id?'更正画像 / 偏好':'添加画像 / 偏好',`<form id="profile-form"><input type="hidden" name="id" value="${e(id||'')}"><input type="hidden" name="expected_version" value="${e(p.version||'')}"><label for="profile-content">内容</label><textarea id="profile-content" name="content" required>${e(p.content||'')}</textarea><div class="two-col"><div><label for="profile-category">类别</label><select id="profile-category" name="category">${Object.entries({background:'背景',preference:'偏好',project_rule:'项目规则',stage_goal:'阶段目标',hypothesis:'待讨论推测'}).map(([k,v])=>`<option value="${k}" ${p.category===k?'selected':''}>${v}</option>`).join('')}</select></div><div><label for="profile-scope">作用域</label><input id="profile-scope" name="scope" value="${e(p.scope||'global')}" list="profile-scope-options" aria-describedby="profile-scope-help" required placeholder="选择建议，或填写 project:项目名"><datalist id="profile-scope-options"><option value="global">个人全局偏好</option><option value="routine:A1">每日一学专属规则</option><option value="routine:A2">每日反思专属规则</option><option value="routine:A3">睡眠打卡专属规则</option></datalist><p class="form-help" id="profile-scope-help">global：个人全局；routine:A1：每日一学；routine:A2：每日反思；routine:A3：睡眠打卡。在聊天中保存的专属规则，也可在这里更正或停用。项目规则仍可填写 project:项目名。</p></div></div><label for="profile-source">来源引用（每行一条）</label><textarea id="profile-source" name="source_refs" data-layout="layout-18" placeholder="活动、原话或材料的稳定定位">${e((p.source_refs||[]).join('\n'))}</textarea><label for="profile-valid">有效期至（可选）</label><input id="profile-valid" type="date" name="valid_until" value="${e(p.valid_until?.slice(0,10)||'')}"><label class="check-row"><input name="confirmed" type="checkbox" ${p.confirmed?'checked':''}>这是我明确确认的背景、偏好或规则</label><p class="form-help">未确认的内容保持待讨论状态，不作为稳定事实。停用画像不等于删除原话。</p>${formActions('保存此版本')}</form>`);}
function growthModal(kind='goal',id='',parentId='',businessDate=''){const x=growthItems(line).find(i=>(i.item_id||i.id)===id)||{};kind=x.kind||kind;openModal(`${id?'修订':'添加'}${kindNames[kind]||'成长记录'} · ${lineNames[line]}`,`<form id="growth-form"><input type="hidden" name="item_id" value="${e(id)}"><input type="hidden" name="original_business_date" value="${e(x.business_date==='unknown'?'unknown':'')}"><input type="hidden" name="expected_version" value="${e(x.version||'')}"><div class="two-col"><div><label for="growth-kind">记录类型</label><select id="growth-kind" name="kind">${Object.entries(kindNames).filter(([k])=>k!=='revision').map(([k,v])=>`<option value="${k}" ${kind===k?'selected':''}>${v}</option>`).join('')}</select></div><div><label for="growth-date">归属日期</label><input id="growth-date" name="business_date" type="date" value="${e(x.business_date==='unknown'?'':x.business_date||businessDate||state.today||today())}"></div></div><label for="growth-content">${kind==='plan'?'目标、约束、近期行动与预期产物':kind==='evaluation'?'你对这份实际成果的评价':kind==='current_state'?'你确认的真实当前状态':'内容'}</label><textarea id="growth-content" name="content" required placeholder="以实际材料为依据，未知的部分可以保持未知。">${e(typeof x.content==='object'?(x.content.text||growthText(x.content)):x.content||'')}</textarea><label for="growth-parent">关联记录（可选）</label><select id="growth-parent" name="parent_id"><option value="">不关联</option>${growthItems(line).filter(i=>(i.item_id||i.id)!==id).map(i=>`<option value="${e(i.item_id||i.id)}" ${(parentId||x.parent_id)===(i.item_id||i.id)?'selected':''}>${e(kindNames[i.kind]||i.kind)} · ${e(growthText(i.content).slice(0,60))}</option>`).join('')}</select><label for="growth-source">证据 / 来源引用（每行一条）</label><textarea id="growth-source" name="source_refs" data-layout="layout-16" placeholder="例如 activity:活动编号、task:任务编号，或材料网址">${e((x.source_refs||[]).join('\n'))}</textarea><div class="two-col"><div><label for="growth-review">下次复盘日期</label><input id="growth-review" type="date" name="review_date" value="${e(x.review_date||shifted(state.today||today(),kind==='plan'?90:7))}"></div><div><label for="growth-until">阶段截止（可选）</label><input id="growth-until" type="date" name="period_end" value="${e(x.content?.period_end||'')}"></div></div><label class="check-row"><input name="confirmed" type="checkbox" ${x.confirmed?'checked':''}>我已核对这条记录，确认它反映我的实际情况</label><p class="form-help">修订保留旧版本。成果评价和当前状态来自你本人的输入；新计划不会自动生成执行授权。</p>${formActions(id?'保存修订版本':'保存记录')}</form>`);}
let deletionGeneration=0;
function deletionQueue(){try{const rows=JSON.parse(storeGet('dsh-deletion-pending')||'[]');return Array.isArray(rows)?rows.filter(x=>typeof(x.id||x.message_id)==='string').map(x=>({...x,id:x.id||x.message_id,kind:x.kind==='import'?'import':'message'})):[];}catch{return [];}}
let deletionPending=deletionQueue();
function deletionUnfinished(result){return result.native_cleanup_pending!==false||result.sqlite_cleanup_pending!==false||result.latest_ledger_protected!==true;}
function rememberDeletion(id,kind,activityId,result={}){const row={id,kind,activity_id:activityId||deletionPending.find(x=>x.id===id&&x.kind===kind)?.activity_id||null,at:new Date().toISOString(),native_cleanup_pending:result.native_cleanup_pending,sqlite_cleanup_pending:result.sqlite_cleanup_pending,latest_ledger_protected:result.latest_ledger_protected};deletionPending=deletionPending.filter(x=>x.id!==id||x.kind!==kind);if(deletionUnfinished(result))deletionPending.push(row);const saved=storeSet('dsh-deletion-pending',JSON.stringify(deletionPending));$$('[data-deletion-pending]').forEach(el=>el.innerHTML=deletionPendingHTML(el.dataset.deletionPending||null));return saved;}
function deletionStatusHTML(result){const rows=[['原生会话清理',result.native_cleanup_pending===false?'当前原生会话副本已逻辑清理':result.native_cleanup_pending===true?'待完成；相关会话保持隔离':'尚未取得确认回执'],['本地数据库清理',result.sqlite_cleanup_pending===false?'本地数据库清理已完成':result.sqlite_cleanup_pending===true?'数据库空间清理待完成，可继续重试':'尚未取得确认回执'],['最新删除账本',result.latest_ledger_protected===true?'最新删除账本已加密保护':result.latest_ledger_protected===false?'尚未完成加密保护，需要继续处理':'尚未取得保护回执，可能尚未配置备份密钥']];return `<dl class="summary-list deletion-status">${rows.map(([title,body])=>`<div class="summary-entry"><dt>${e(title)}</dt><dd>${e(body)}</dd></div>`).join('')}</dl>`;}
function deletionPendingHTML(activityId=null){const rows=deletionPending.filter(x=>!activityId||x.activity_id===activityId);return rows.length?`<section class="card deletion-pending"><h2>删除处理待确认</h2><p class="subtle">这里只保留处理编号和状态，不保存已删除正文。可以重新核对范围并继续清理。</p>${rows.map(x=>`<div class="deletion-pending-item"><p class="muted small">${x.kind==='import'?'导入批次移除':'原话删除'} · 提交于 ${e(timeString(x.at))}</p>${deletionStatusHTML(x)}<button class="small" data-action="deletion-retry" data-id="${e(x.id)}" data-kind="${e(x.kind)}">核对范围并继续清理</button></div>`).join('')}</section>`:'';}
async function deleteModal(id,source='',kind='message'){
 const generation=++deletionGeneration,imported=kind==='import',title=imported?'核对批次移除范围':'核对删除范围';
 openModal(title,`<div id="deletion-loading" data-id="${e(id)}" role="status">正在读取当前关联范围…</div>`);
 try{
  const plan=await action(imported?'import_removal_plan':'deletion_plan',imported?{batch_id:id}:{message_id:id});
  if(generation!==deletionGeneration||!$('#modal').open||$('#deletion-loading')?.dataset.id!==id)return;
  if(typeof plan.token!=='string'||!plan.token)throw new Error('服务端未返回有效删除计划，尚未执行删除。');
  const affected=[['activity_ids','关联活动'],['task_ids','关联委托'],['native_session_ids','原生会话'],['attachment_ids','直接附件'],['source_refs','来源引用']].filter(([key])=>!imported||Array.isArray(plan[key]));
  const legacy=Array.isArray(plan.legacy_session_ids)?plan.legacy_session_ids:[];
  openModal(title,`<form id="delete-form"><input type="hidden" name="record_id" value="${e(id)}"><input type="hidden" name="target_kind" value="${e(kind)}"><input type="hidden" name="plan_token" value="${e(plan.token)}"><div class="notice error">${e(plan.scope||'删除目标内容及相关派生项。请核对以下影响范围。')}</div><dl class="deletion-counts">${affected.map(([key,label])=>`<div><dt>${label}</dt><dd data-delete-count="${key}">${Array.isArray(plan[key])?plan[key].length:0}</dd></div>`).join('')}</dl>${legacy.length?`<div class="notice" id="deletion-legacy"><strong>旧会话保守失效范围：${legacy.length} 个</strong><p>这些旧会话缺少完整的上下文来源记录，可能曾使用关联画像，因此其模型派生内容会一并失效；其他独立用户原文仍保留。</p><details><summary>查看受影响旧会话编号</summary><p class="code-text">${legacy.map(e).join('<br>')}</p></details></div>`:'<p class="subtle">本计划未额外纳入缺少来源记录的旧会话。</p>'}<p class="subtle">${imported?'仅移除此批新增记录，导入前已存在的相同内容保留。':''}关联模型回复、摘要和旧任务成果会失效，相关委托暂停。其他独立原话、更正、委托及评价即使含相同文字也保留，仍可用于后续对话。历史加密备份按保留期退出，恢复时须合并最新删除账本；已有离线导出和独立用户文件需另外处理。</p><details class="deletion-identities"><summary>查看影响范围编号</summary>${affected.map(([key,label])=>`<p class="code-text"><strong>${label}</strong><br>${(Array.isArray(plan[key])?plan[key]:[]).map(e).join('<br>')||'无'}</p>`).join('')}</details><div id="deletion-error" role="alert"></div><label for="delete-source">删除说明</label><input id="delete-source" name="source" value="${e(source)}" placeholder="可留空"><label class="check-row"><input type="checkbox" name="confirm" required>我已核对以上范围，确认${imported?'移除此批新增记录':'删除目标原话'}并使相关派生内容失效</label>${formActions(imported?'按此范围移除':'按此范围删除')}<button type="button" class="small ghost" data-action="deletion-refresh" data-id="${e(id)}" data-kind="${e(kind)}">重新获取删除范围</button></form>`);
 }catch(err){
  if(generation===deletionGeneration&&$('#modal').open&&$('#deletion-loading')?.dataset.id===id)openModal('删除范围尚未取得',`<div class="notice error">${e(err.message)}</div><button data-action="deletion-retry" data-id="${e(id)}" data-kind="${e(kind)}">重新获取删除范围</button>`);
 }
}
async function submitDeletion(form){
 const fd=new FormData(form),id=String(fd.get('record_id')||''),kind=String(fd.get('target_kind')||'message'),imported=kind==='import',token=String(fd.get('plan_token')||''),source=String(fd.get('source')||'用户在删除控件明确确认');
 if(!token||!fd.has('confirm'))throw new Error('请重新获取删除范围并明确确认。');
 const activityId=imported?null:currentActivity?.activity.id||deletionPending.find(x=>x.id===id&&x.kind===kind)?.activity_id;
 const localSaved=rememberDeletion(id,kind,activityId);
 try{
  const result=await action(imported?'import_remove':'delete_message',{...(imported?{batch_id:id}:{message_id:id}),plan_token:token,scope:'raw_and_derived',source});
  rememberDeletion(id,kind,activityId,result);
  openModal('删除处理结果',`<div class="notice ${deletionUnfinished(result)?'':'info'}">${deletionUnfinished(result)?'请求已处理，仍有清理或账本保护步骤待确认。':'当前实例中的目标记录与相关派生内容已按回执处理。'}</div>${deletionStatusHTML(result)}<p class="subtle">${imported?'导入前已存在的记录保留。':''}其他独立原话、更正、委托及评价即使含相同文字也保留，仍可用于后续对话；旧模型派生回复失效。历史加密备份受保留期和最新删除账本约束；这不表示已有离线导出或所有副本均已销毁。</p>${!localSaved?'<p class="notice error">此浏览器未能保存后续处理入口，请保留当前窗口并记录本次处理编号。</p>':''}<div class="form-actions"><button data-action="modal-close">关闭</button>${deletionUnfinished(result)?`<button class="primary" data-action="deletion-retry" data-id="${e(id)}" data-kind="${e(kind)}">核对范围并继续清理</button>`:''}</div>`);
  if(imported)loadRoute().catch(err=>toast('移除回执已取得；页面同步暂未完成：'+err.message,true));
  else if(route==='activity'&&currentActivity?.activity.id===activityId)updateActivity(activityId).catch(err=>toast('删除回执已取得；页面同步暂未完成：'+err.message,true));
 }catch(err){
  if(!form.isConnected)throw err;
  const changed=/重新核对.*范围|关联记录已经变化|(?:删除|移除)计划.*(?:变化|过期)/.test(err.message);
  if(changed){form.elements.plan_token.value='';form.elements.confirm.checked=false;form.dataset.planInvalid='true';}
  $('#deletion-error').innerHTML=`<div class="notice error">${e(err.message)}${changed?'。请点击“重新获取删除范围”，核对后再次确认。':'。尚未确认所有处理步骤；可重试本次提交或重新核对范围。'}</div>`;
  if(changed){const button=form.querySelector('button[type="submit"]');if(button)button.disabled=true;}
 }
}
async function sendMessage(retry=false){if(busy||!currentActivity)return;const id=currentActivity.activity.id,draft=getDraft(id);const input=$('#message-input');draft.body=input?.value??draft.body;if(draft.pending&&!retry){toast('上次提交结果尚未确认，请先点击“重试提交”。',true);return;}if(!retry){if(!draft.body.trim())return;draft.pending={submission_id:uid(),body:draft.body,...(draft.question?{call_id:draft.question.call_id,question_id:draft.question.question_id}:{})};}if(!draft.pending)return;const pending={...draft.pending};persistDraft(id);busy=true;const button=$('#send-button');if(button)button.disabled=true;draftStatus(id,'正在提交，等待服务端持久回执…');try{const result=await action('message',{activity_id:id,...pending});if(!result.receipt)throw new Error('服务端尚未返回持久回执，未确认保存。请保留草稿后重试。');draft.pending=null;draft.question=null;if(currentActivity?.activity.id===id)renderAnswerTarget(id);if(draft.body===pending.body){draft.body='';if(currentActivity?.activity.id===id){const activeInput=$('#message-input');if(activeInput)activeInput.value='';scheduleComposerResize();}}persistDraft(id);if(currentActivity?.activity.id===id)draftStatus(id,result.processing_state==='failed'||result.processing_state==='pending'?'回答已保存，处理稍后继续。':'已收到持久回执，原话已保存。');await updateActivity(id);if(result.activity?.id&&result.activity.id!==id)toast('补记已归属指定历史活动，可在历史入口继续。');}catch(err){if(currentActivity?.activity.id===id)draftStatus(id,err.message,true);toast(err.message,true);}finally{busy=false;if(button)button.disabled=false;}}
async function updateActivity(id){const readGeneration=++activityReadGeneration,routeGeneration=loadGeneration;const data=await api('/api/activity?id='+encodeURIComponent(id));if(readGeneration!==activityReadGeneration||routeGeneration!==loadGeneration||route!=='activity'||routeId!==id||currentActivity?.activity.id!==id)return;const previous=currentActivity;currentActivity=data;activityAppliedGeneration=readGeneration;if(!$('#messages'))return;updateConversation(data,previous);if(activityDisplayStatus(data.activity)!==activityDisplayStatus(previous?.activity))$('#activity-status').innerHTML=tag(activityDisplayStatus(data.activity));if(['A2','A3'].includes(data.activity.routine)&&!sameData(data.summary,previous?.summary))$('#activity-summary').innerHTML=(data.activity.routine==='A2'?reflectionDimensionsHTML(data):'')+summaryHTML(data.summary);if(data.activity.notification_state!==previous?.activity.notification_state)$('#notification-state').textContent=notificationLabel(data.activity.notification_state);if(!sameData(data.attachments,previous?.attachments))$('#attachments').innerHTML=attachmentsHTML(data.attachments||[]);if(!sameData(data.questions,previous?.questions))$('#native-questions').innerHTML=questionsHTML(data.questions||[]);if(!sameData(data.messages,previous?.messages)||!sameData(data.reflection,previous?.reflection)||!sameData(data.reflection_dimensions,previous?.reflection_dimensions))updateActivitySidebar(data);ackPresented(data.activity);}
let loadGeneration=0,eventStream=null,liveLease=null;
function connectEvents(){if(eventStream||!state||document.visibilityState!=='visible')return;const stream=new EventSource('/api/events');eventStream=stream;stream.addEventListener('hello',event=>{if(eventStream!==stream)return;try{liveLease=JSON.parse(event.data).lease;markConnected();}catch{liveLease=null;}});stream.onopen=()=>{if(eventStream===stream)markConnected();};stream.onerror=()=>{if(eventStream!==stream)return;stopEvents();markDisconnected();};stream.addEventListener('activity',event=>{if(eventStream!==stream)return;try{const a=JSON.parse(event.data);if(document.visibilityState==='visible'&&Date.now()-lastInteraction<300000){toast(`${routineInfo[a.routine]?.name||'活动'}已就绪，可从侧栏打开。`);requestAnimationFrame(()=>ackPresented({...a,id:a.id||a.activity_id}));}}catch{}});}
