function updateActivitySidebar(data){const dimensions=$('.reflection-dimensions');if(dimensions)dimensions.outerHTML=reflectionDimensionsHTML(data);const list=$('#sidebar-message-list');if(list)list.innerHTML=messageManagementHTML(data.messages||[]);}
function shellKeydown(event){const sidebar=$('#app-sidebar');if(!sidebar||!$('.app-shell')?.classList.contains('sidebar-open')||$('#modal').open)return;if(event.key==='Escape'){event.preventDefault();setSidebar(false);return;}if(event.key==='Tab'){const nodes=[...sidebar.querySelectorAll('a[href],button:not([disabled]),input:not([disabled]),select,textarea,summary,[tabindex="0"]')].filter(x=>x.getClientRects().length);if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&(document.activeElement===first||!sidebar.contains(document.activeElement))){event.preventDefault();last.focus();}else if(!event.shiftKey&&(document.activeElement===last||!sidebar.contains(document.activeElement))){event.preventDefault();first.focus();}}}
