async function handleAction(el){if(await handleChronicleAction(el))return;const type=el.dataset.action;switch(type){case 'theme-toggle':if(!applyTheme(currentTheme()==='dark'?'light':'dark',true))toast('已切换显示；此浏览器未能保存选择，下次打开可能恢复蓝白。',true);break;case 'retry-connection':stopEvents();await recoverConnection();break;case 'auth-refresh':await renderLogin();break;case 'password-change':openModal('更改密码',`<form id="password-form"><label for="current-password">当前密码</label><input id="current-password" name="current_password" type="password" autocomplete="current-password" required><label for="new-password">新密码</label><input id="new-password" name="new_password" type="password" autocomplete="new-password" minlength="10" maxlength="256" required><label for="new-password-confirm">再次输入新密码</label><input id="new-password-confirm" name="confirm_password" type="password" autocomplete="new-password" required><p class="subtle">保存后其他设备需用新密码登录。</p>${formActions('保存新密码')}</form>`);break;case 'sidebar-toggle':setSidebar(!$('.app-shell')?.classList.contains('sidebar-open'));break;case 'sidebar-close':setSidebar(false);break;case 'sidebar-panel':sidebarPanel(el.dataset.panel);break;case 'navigate':navTo(el.dataset.page);break;case 'refresh':await loadRoute();break;case 'open-activity':navTo('activity',el.dataset.id);break;case 'open-routine':{el.disabled=true;const r=await action('ensure_activity',{routine:el.dataset.routine,date:el.dataset.date});const a=r.activity||r;navTo('activity',a.id);break;}case 'history-add':{const d=$('#history-other').value;if(!d||d>(state.today||today()))throw new Error('请选择今天或之前的有效日期。');selectedDates.add(d);date=d;await refreshState();renderHistory();break;}case 'history-clear':selectedDates.clear();renderHistory();break;case 'natural-retry':{const p=getNaturalPending();if(p){const form=$('#natural-form');form.elements.body.value=p.body;await handleForm(form);}break;}case 'modal-close':closeModal();break;case 'source-open':{const value=await api('/api/source?ref='+encodeURIComponent(el.dataset.ref));openModal('证据与原文',`<p class="code-text">${e(el.dataset.ref)}</p><div class="task-result">${e(readable(value))}</div>`);break;}case 'task-new':taskModal();break;case 'task-review':reviewModal(el.dataset.id,el.dataset.version,el.dataset.review);break;case 'task-run':await action('task_run',{task_id:el.dataset.id});toast('已请求服务端执行。');await loadRoute();break;case 'routine-settings-edit':routineSettingsModal(el.dataset.routine);break;case 'routine-dimension-add':{const rows=$$('.routine-dimension',$('#routine-dimensions'));if(rows.length>=12)throw Error('最多设置 12 个反思方面。');$('#routine-dimensions').insertAdjacentHTML('beforeend',routineDimensionRow());$('#routine-dimensions').lastElementChild.querySelector('input').focus();break;}case 'routine-dimension-remove':{const rows=$$('.routine-dimension',$('#routine-dimensions'));if(rows.length<=1)throw Error('请至少保留一个反思方面。');const row=el.closest('.routine-dimension'),focus=(row.nextElementSibling||row.previousElementSibling)?.querySelector('input');row.remove();focus?.focus();break;}case 'schedule-edit':scheduleModal(el.dataset.routine);break;case 'schedule-daily':$$('input[name=weekdays]',$('#modal')).forEach(x=>x.checked=true);$('#schedule-pause').value='';break;case 'activity-control':{const a=currentActivity.activity;await action('activity_control',{activity_id:a.id,action:el.dataset.control,...(el.dataset.control==='bookmark'?{value:!a.bookmarked}:{})});toast('活动状态已保存，仍可继续交流。');await loadRoute();break;}case 'snooze':openModal('稍后提醒一次',`<form id="snooze-form"><label for="snooze-time">提醒时间（Asia/Shanghai）</label><input name="remind_at" id="snooze-time" type="datetime-local" required><p class="form-help">新选择会替换此活动尚未发送的稍后提醒。</p>${formActions('保存提醒')}</form>`);break;case 'question-answer':case 'question-option':{const id=currentActivity.activity.id;getDraft(id).question={call_id:el.dataset.call,question_id:el.dataset.question,label:el.dataset.label};if(type==='question-option'){$('#message-input').value=el.dataset.value;getDraft(id).body=el.dataset.value;}persistDraft(id);renderAnswerTarget(id);scheduleComposerResize();$('#message-input').focus();break;}case 'question-cancel':getDraft(currentActivity.activity.id).question=null;persistDraft(currentActivity.activity.id);renderAnswerTarget(currentActivity.activity.id);break;case 'retry-send':await sendMessage(true);break;case 'correct':correctionModal();break;case 'retry-processing':await action('retry',{activity_id:currentActivity.activity.id});toast('已请求重试待处理步骤，原话无需重答。');await updateActivity(currentActivity.activity.id);break;case 'retry-all':await action('retry',{});toast('已请求重试失败步骤。');await loadRoute();break;case 'journal-page':journalPage=Math.max(0,journalPage+Number(el.dataset.offset));renderTranscript();break;case 'journal-day':journalPage=0;journalMode='day';date=shifted(date,Number(el.dataset.offset));await refreshState();renderTranscript();break;case 'growth-line':line=el.dataset.line;navTo('growth',line);break;case 'growth-week':weekOffset=Number(el.dataset.offset);await refreshState();renderGrowth();break;case 'growth-new':growthModal(el.dataset.kind||'goal','','',el.dataset.date||'');break;case 'growth-edit':growthModal('goal',el.dataset.id);break;case 'growth-evaluate':growthModal('evaluation','',el.dataset.id);break;case 'profile-new':profileModal();break;case 'profile-edit':profileModal(el.dataset.id);break;case 'profile-disable':await action('profile_disable',{id:el.dataset.id});toast('已停用此项画像，原话仍保留。');await loadRoute();break;case 'message-delete':case 'deletion-retry':await deleteModal(el.dataset.id,'',el.dataset.kind||'message');break;case 'deletion-refresh':await deleteModal(el.dataset.id,$('#delete-form')?.elements.source.value||'',el.dataset.kind||'message');break;case 'import-apply':{if(!preview)throw new Error('请先预览本次导入。');const r=await action('import_apply',{...preview.params,preview_token:preview.result.preview_token});toast(`导入完成：${r.counts?.new??r.count??0} 条新增。`);preview=null;await loadRoute();break;}case 'import-remove':await deleteModal(el.dataset.id,'','import');break;case 'cleanup':{const r=await action('cleanup',{scope:'regenerable'});toast(r.message||'可再生缓存清理完成。');await loadRoute();break;}case 'attachment-upload':{const file=$('#attachment-file').files[0];if(!file)throw new Error('请先选择附件。');if(file.size>10_000_000)throw new Error('单个附件请控制在 10 MB 内。');const buffer=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<buffer.length;i+=8192)binary+=String.fromCharCode(...buffer.subarray(i,i+8192));await action('attachment_upload',{activity_id:currentActivity.activity.id,filename:file.name,content_base64:btoa(binary),mime_type:file.type});toast('附件已保存。');await updateActivity(currentActivity.activity.id);$('#attachment-file').value='';break;}case 'logout':await api('/api/logout',{});stopEvents();await renderLogin();break;}}
async function handleForm(form){if(await handleChronicleForm(form))return;const fd=new FormData(form),get=k=>String(fd.get(k)||'');switch(form.getAttribute('id')){case 'account-setup-form':case 'login-form':try{const setup=form.getAttribute('id')==='account-setup-form';if(setup&&get('password')!==get('confirm_password'))throw Error('两次输入的密码不一致。');await api(setup?'/api/auth/setup':'/api/login',{username:get('username'),password:get('password'),remember:fd.has('remember')});authInfo={configured:true,authenticated:true};form.reset();await loadRoute();}catch(err){if($('#login-error'))$('#login-error').textContent=err.message;}return;case 'password-form':if(get('new_password')!==get('confirm_password'))throw Error('两次输入的密码不一致。');await api('/api/auth/password',{current_password:get('current_password'),new_password:get('new_password'),remember:true});form.reset();closeModal();toast('密码已更新，其他设备需重新登录。');return;case 'message-form':await sendMessage();return;case 'natural-form':{let pending=getNaturalPending();if(pending&&pending.body!==get('body'))throw new Error('上次补记尚未确认，请先点击“重试原指令”；新指令暂未发送。');if(!pending){pending={body:get('body'),submission_id:uid()};naturalPending=pending;storeSet('dsh-natural-pending',JSON.stringify(pending));}$('#natural-pending').innerHTML=naturalPendingHTML();const r=await action('natural',pending);naturalPending=null;storeDel('dsh-natural-pending');if($('#natural-pending'))$('#natural-pending').innerHTML='';if(r.activities?.length>1){r.activities.forEach(a=>selectedDates.add(a.business_date));await refreshState();renderHistory();toast(r.message||'已定位所选日期，可逐项继续。');}else if(r.activity?.id)navTo('activity',r.activity.id);else toast(r.message||'请补充明确的日期和活动类型。');return;}case 'journal-form':date=get('date')||today();query=get('q');journalMode=get('journal_mode')||'day';journalPage=0;await refreshState();renderTranscript();return;case 'task-form':await action('task_create',{submission_id:get('submission_id'),goal:get('goal'),owner:get('owner'),inputs:get('inputs'),deliverable:get('deliverable'),acceptance:get('acceptance'),run_at:get('run_at')?get('run_at')+':00+08:00':null,interval_days:Number(get('interval_days'))||null,source_activity_id:get('source_activity_id')||null});closeModal();toast('委托已建立，执行安排可在看板查看。');navTo('tasks');return;case 'review-form':await action('task_review',{task_id:get('task_id'),version:Number(get('version')),action:get('action'),input:get('input')});closeModal();toast('你的操作已绑定此成果版本保存。');await loadRoute();return;case 'routine-settings-form':await saveRoutineSettings(form);return;case 'schedule-form':{const days=fd.getAll('weekdays').map(Number);if(!days.length)throw new Error('请选择至少一天；需要暂停时请设置暂停日期。');const source=`用户在日程设置明确将 ${get('routine')} 调整为 ${get('time')}，星期 ${days.map(x=>x+1).join('、')}，${get('paused_until')?'暂停到 '+get('paused_until'):'不暂停'}，Asia/Shanghai。`;const payload={routine:get('routine'),time:get('time'),weekdays:days,paused_until:get('paused_until')||null,source,...(get('expected_updated_at')?{expected_updated_at:get('expected_updated_at')}:{})},signature=JSON.stringify(payload);if(form.dataset.submittedPayload&&form.dataset.submittedPayload!==signature)form.elements.submission_id.value=uid();form.dataset.submittedPayload=signature;const r=await action('schedule',{...payload,submission_id:form.elements.submission_id.value});closeModal();toast(`日程已更新${r.next_at?'，下一次 '+timeString(r.next_at):''}。`);await loadRoute();return;}case 'snooze-form':{const at=get('remind_at')+':00+08:00';if(new Date(at)<=new Date())throw new Error('提醒时间需要晚于现在。');await action('activity_control',{activity_id:currentActivity.activity.id,action:'snooze',remind_at:at});closeModal();toast(`已设置 ${timeString(at)}（上海时间）提醒一次。`);return;}case 'correction-form':{const fields={};$$('textarea[data-original]',form).forEach(input=>{if(input.value!==input.dataset.original)fields[input.name]=input.value||null;});if(!Object.keys(fields).length)throw new Error('尚未修改记录字段。');await action('correction',{activity_id:currentActivity.activity.id,fields,source:get('source')||'用户在记录更正控件明确修改字段'});closeModal();toast('更正已保存，会持续用于后续摘要。');await updateActivity(currentActivity.activity.id);return;}case 'profile-form':await action('profile_save',{id:get('id')||undefined,item_id:get('id')||undefined,expected_version:Number(get('expected_version'))||undefined,content:get('content'),category:get('category'),scope:get('scope'),source_refs:get('source_refs').split('\n').map(x=>x.trim()).filter(Boolean),confirmed:fd.has('confirmed'),valid_until:get('valid_until')||null,user_input:get('content')});closeModal();toast('画像版本已保存。');await loadRoute();return;case 'growth-form':{const kind=get('kind');if(['evaluation','current_state'].includes(kind)&&!fd.has('confirmed'))throw new Error('成果评价和当前状态需要你勾选核对确认。');const originalContent=growthItems(line).find(x=>(x.item_id||x.id)===get('item_id'))?.content;const content={...(originalContent&&typeof originalContent==='object'?originalContent:{}),text:get('content')};if(get('period_end'))content.period_end=get('period_end');if(get('review_date'))content.review_date=get('review_date');await action('growth_save',{line,kind,content,item_id:get('item_id')||undefined,expected_version:Number(get('expected_version'))||undefined,parent_id:get('parent_id')||null,source_refs:get('source_refs').split('\n').map(x=>x.trim()).filter(Boolean),business_date:get('business_date')||get('original_business_date'),review_date:get('review_date')||null,confirmed:fd.has('confirmed'),user_input:get('content')});closeModal();toast('成长记录及其引用已保存。');await loadRoute();return;}case 'delete-form':await submitDeletion(form);return;case 'import-form':{const file=$('#import-file').files[0];if(!file)throw new Error('请先选择历史资料文件。');if(file.size>8_000_000)throw new Error('浏览器导入单个文件上限为 8 MB，请拆分较大的导出文件后分别导入。');const params={source:get('source'),channel:get('source'),kind:get('kind'),scope:get('scope'),filename:file.name,content:await file.text()};if(params.kind==='instructions'&&!params.scope.startsWith('project:'))throw new Error('项目规则的作用域需要以 project: 开头。');const result=await action('import_preview',params);preview={params,result};$('#import-preview').innerHTML=`<div class="notice info" data-layout="layout-7"><strong>${e(file.name)}</strong><br>总计 ${e(result.counts?.total??result.count??0)} · 新增 ${e(result.counts?.new??0)} · 重复 ${e(result.counts?.duplicates??result.duplicates??0)} · 删除账本过滤 ${e(result.counts?.deleted??0)}<br>日期范围：${e((result.date_range||result.range||[]).join(' — '))||'来源未提供'}<br>失败 ${(result.failures||[]).length} · 缺失附件 ${(result.missing_attachments||[]).length}</div>${(result.failures||[]).length?`<details><summary>失败项</summary><pre class="code-text">${e(readable(result.failures))}</pre></details>`:''}${(result.warnings||[]).length?`<p class="subtle">${e(readable(result.warnings))}</p>`:''}${(result.missing_attachments||[]).length?`<details><summary>缺失附件清单</summary><pre class="code-text">${e(readable(result.missing_attachments))}</pre></details>`:''}<details><summary class="small">预览来源记录</summary><div class="task-result">${e(readable(result.sample||result.items||[]))}</div></details><div class="form-actions"><button class="primary" data-action="import-apply">应用这次预览的导入</button></div>`;return;}}}
document.addEventListener('click',async event=>{lastInteraction=Date.now();const el=event.target.closest('[data-action]');if(!el)return;event.preventDefault();if(el.disabled)return;try{await handleAction(el);}catch(err){toast(err.message||String(err),true);}finally{if(el.isConnected)el.disabled=false;}});
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target;const buttons=$$('button[type=submit]',form);buttons.forEach(x=>x.disabled=true);try{await handleForm(form);}catch(err){toast(err.message||String(err),true);}finally{buttons.forEach(x=>x.disabled=form.dataset.planInvalid==='true');}});
document.addEventListener('input',event=>{lastInteraction=Date.now();if(event.target.id==='message-input'&&currentActivity){const id=currentActivity.activity.id;getDraft(id).body=event.target.value;const saved=persistDraft(id);draftStatus(id,saved?'':'本地草稿保存失败，请先复制文字；尚未发送。',!saved);scheduleComposerResize();}});
document.addEventListener('compositionend',event=>{if(event.target.id==='message-input')scheduleComposerResize();});
window.visualViewport?.addEventListener('resize',scheduleComposerResize);
document.addEventListener('change',async event=>{if(event.target.name==='import-message')updateImportSelection();if(event.target.id==='calendar-all-day')toggleCalendarAllDay();if(event.target.name==='history-date'){const d=event.target.value;if(event.target.checked)selectedDates.add(d);else selectedDates.delete(d);event.target.closest('.day-chip').classList.toggle('selected',event.target.checked);renderHistory();}});
document.addEventListener('keydown',event=>{lastInteraction=Date.now();if(event.target.id==='message-input'&&event.key==='Enter'&&!event.isComposing&&event.keyCode!==229&&(event.ctrlKey||event.metaKey)){event.preventDefault();sendMessage();}});
window.addEventListener('hashchange',()=>{if(authInfo?.configured)loadRoute();});

window.addEventListener('online',resumeConnection);
window.addEventListener('offline',()=>{stopEvents();markDisconnected();});
window.addEventListener('focus',resumeConnection);
window.addEventListener('pageshow',resumeConnection);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')resumeConnection();else{stopEvents();clearTimeout(reconnectTimer);reconnectTimer=null;}});
setInterval(async()=>{if(!state||polling||recoveryPromise||connectionState!=='connected'||document.visibilityState!=='visible'||$('#modal').open)return;polling=true;try{if(route==='activity'&&routeId)await updateActivity(routeId);else if(['feedback','study'].includes(route))await updateSupportPage();else {await refreshState();if(route==='today')renderToday();if(route==='tasks')renderTasks();}connectEvents();}catch{markDisconnected();}finally{polling=false;}},8000);
async function bootstrap(){try{authInfo=await authStatus();if(!authInfo.configured){await renderLogin();return;}if(!location.hash){const last=storeGet('dsh-last-activity');location.hash=last?'#activity/'+encodeURIComponent(last):'#chat';}else await loadRoute();}catch{await renderLogin();}}
let chronicleFilter='recorded',chronicleQuery='',chronicleYear='',calendarView='month',calendarShowCancelled=false;
function avatarHTML(kind=''){return `<img src="/qiju-avatar.png" class="qiju-avatar ${kind}" alt="起居，执笔的蓝发鱼系史官" width="64" height="64">`;}
function historicalDeliveryListHTML(items){if(!items.length)return '';return `<details class="historical-delivery-list"><summary>历史推送材料 <span>${items.length}</span></summary><p>来源记为已推送，未推断已读。</p>${items.map(x=>`<button class="historical-delivery-item" data-action="learning-history-open" data-id="${e(x.id)}"><span>${e(x.title||'一份历史学习材料')}</span>${x.date_evidence?`<small>${e(evidenceDateLabel(x.date_evidence))}</small>`:''}</button>`).join('')}</details>`;}
function historicalDeliveryModal(item){openModal(item.title||'历史学习材料',`<div class="historical-delivery-detail"><p class="notice info">来源记为已推送，未推断已读。这里保留历史材料索引，不代表已经恢复完整课程正文。</p>${item.body?`<div class="markdown-body">${renderMarkdown(item.body)}</div>`:''}${item.bibliographic_source?`<p class="source-date-note">材料出处：${e(typeof item.bibliographic_source==='string'?item.bibliographic_source:readable(item.bibliographic_source))}</p>`:''}${item.date_evidence?`<p class="source-date-note">日期依据：${e(evidenceDateLabel(item.date_evidence))}</p>`:''}<div class="historical-delivery-sources">${(item.source_refs||[]).map((ref,n)=>`<button class="small ghost" data-action="source-open" data-ref="${e(ref)}">${icon('link')}查看原始来源 ${n+1}</button>`).join('')}</div></div>`);}
function routineProjectsHTML(){return ['A1','A3','A2'].map(r=>{const project=(state?.routine_projects||[]).find(p=>p.routine===r)||{},items=[...(project.activities||(state?.activities||[]).filter(a=>a.routine===r))].sort((a,b)=>String(b.business_date).localeCompare(String(a.business_date))),selected=items.some(a=>route==='activity'&&routeId===a.id);return `<details class="routine-folder" data-routine="${r}" ${selected?'open':''}><summary><span class="folder-symbol">${icon('folder')}</span><span>${e(project.name||routineInfo[r].name)}</span><small>${e(project.count??items.length)}</small><span class="folder-chevron">${icon('chevron')}</span></summary><div class="folder-contents"><a class="folder-today routine-settings-shortcut" href="#settings/${r}" aria-label="${e(routineInfo[r].name)}设置">${icon("settings")}<span>${r==='A1'?'内容与打卡时间':r==='A2'?'方面与打卡时间':'打卡时间'}</span></a><button class="folder-today" data-action="open-routine" data-routine="${r}" data-date="${e(state.today||today())}">${icon('plus')}<span>打开今天</span></button>${items.map(a=>`<a class="project-file${route==='activity'&&routeId===a.id?' active':''}" href="#activity/${encodeURIComponent(a.id)}" ${route==='activity'&&routeId===a.id?'aria-current="page"':''}><span>${icon(routineInfo[r].icon)}</span><time datetime="${e(a.business_date)}">${e(a.business_date)}</time><span class="project-status" title="${e(statuses[activityDisplayStatus(a)]||activityDisplayStatus(a))}" aria-label="${e(statuses[activityDisplayStatus(a)]||activityDisplayStatus(a))}">${activityStatusIcon(a)}</span></a>`).join('')||'<p class="sidebar-empty">还没有记录，随时开始。</p>'}${r==='A1'?historicalDeliveryListHTML(project.historical_deliveries||[]):''}</div></details>`;}).join('');}
function chronicleSourcesHTML(refs){return (refs||[]).map((ref,index)=>`<button class="source-link" data-action="source-open" data-ref="${e(ref)}" title="${e(ref)}">${icon('link')}${String(ref).startsWith('calendar:')?'日程记录':'原话 '+(index+1)}</button>`).join('');}
function chronicleRows(){return Array.isArray(state.chronicle)?state.chronicle:(state.chronicle?.entries||[]);}
function chronicleName(){return state.chronicle_settings?.user_title||'用户';}
function chronicleEntryHTML(row){const candidate=row.status==='candidate';return `<article class="chronicle-entry" data-chronicle-id="${e(row.id)}"><div class="chronicle-date"><time datetime="${e(row.business_date||'')}">${row.business_date?e(row.business_date.slice(5).replace('-','月')+'日'):e(row.date_label||'日期未知')}</time>${chronicleDateBasis(row)?`<span class="chronicle-date-basis">${e(chronicleDateBasis(row))}</span>`:''}<small>${e(row.kind_label||({reflection:'反思',sleep:'起居',chat:'日常',growth:'成长',import:'历史材料',calendar:'日程'}[row.kind])||'个人记载')}</small></div><div class="chronicle-entry-body"><div class="chronicle-entry-heading"><h2>${e(row.title||'一段记录')}</h2>${candidate?'<span class="tag">待整理</span>':''}</div><p class="chronicle-prose">${e(row.body||'')}</p><footer><div class="chronicle-sources">${row.activity_id?`<a class="source-link" href="#activity/${encodeURIComponent(row.activity_id)}">${icon('chat')}回到这段对话</a>`:''}${chronicleSourcesHTML(row.source_refs||[])}${(row.links||[]).filter(x=>/^https?:\/\//.test(x.url||'')||/^#calendar\//.test(x.url||'')).map(x=>`<a class="source-link" href="${e(x.url)}" ${x.url.startsWith('#')?'':'target="_blank" rel="noreferrer"'}>${icon('link')}${e(x.title||x.label||'关联资料')}</a>`).join('')}</div>${row.activity_id||row.import_id||row.compiled_profile_id?`<div class="chronicle-entry-actions">${candidate?`<button class="small" data-action="chronicle-edit" data-id="${e(row.id)}">补充这条线索</button>`:iconButton('更正这条记载','edit',`data-action="chronicle-edit" data-id="${e(row.id)}"`)}${iconButton('暂不记载，保留原话','archive',`data-action="chronicle-exclude" data-id="${e(row.id)}"`)}</div>`:''}</footer></div></article>`;}
function renderChronicle(){const rows=chronicleRows(),recorded=rows.filter(x=>x.status==='recorded'),candidates=rows.filter(x=>x.status==='candidate'),years=[...new Set(rows.map(x=>(x.business_date||'').slice(0,4)).filter(Boolean))].sort().reverse();let chosen=chronicleFilter==='candidate'?candidates:recorded;if(chronicleYear)chosen=chosen.filter(x=>(x.business_date||'').startsWith(chronicleYear));if(chronicleQuery.trim())chosen=chosen.filter(x=>(x.title+' '+x.body).toLowerCase().includes(chronicleQuery.trim().toLowerCase()));chosen=[...chosen].sort((a,b)=>String(b.business_date||'').localeCompare(String(a.business_date||'')));let lastYear='';$('#page').innerHTML=`<section class="chronicle-cover"><div class="chronicle-identity">${avatarHTML('chronicle-avatar')}<div><p class="eyebrow">起居 · 个人史秉笔史官</p><h1>${e(chronicleName())}的个人史</h1><p class="subtle">起居依据对话与资料自然记下经历、变化与选择。你可以随时补充或更正。</p></div></div><a class="quiet-link" href="#transcript">${icon('archive')}对话原文${icon('arrow')}</a></section><div class="chronicle-toolbar"><div class="segmented" role="group" aria-label="个人史记录范围"><button class="${chronicleFilter==='recorded'?'selected':''}" data-action="chronicle-filter" data-filter="recorded" aria-pressed="${chronicleFilter==='recorded'}">已记载 <span>${recorded.length}</span></button><button class="${chronicleFilter==='candidate'?'selected':''}" data-action="chronicle-filter" data-filter="candidate" aria-pressed="${chronicleFilter==='candidate'}">待整理 <span>${candidates.length}</span></button></div><form id="chronicle-filter-form" class="chronicle-search"><select name="year" aria-label="个人史年份"><option value="">全部年份</option>${years.map(y=>`<option ${chronicleYear===y?'selected':''} value="${e(y)}">${e(y)}年</option>`).join('')}</select><input name="q" value="${e(chronicleQuery)}" placeholder="查找一段经历…" aria-label="搜索个人史"><button type="submit" class="icon-button" aria-label="查找个人史" title="查找个人史">${icon('arrow')}</button></form></div>${chronicleFilter==='candidate'?'<p class="chronicle-note">这里保留信息不足或尚未完成整理的线索。来源充分的史事由起居自动记载；计划、推测和助手建议会与已发生的事分开。</p>':''}<section class="chronicle-timeline">${chosen.length?chosen.map(row=>{const yr=(row.business_date||'').slice(0,4)||(row.date_label?'年份未核':'日期未知');const header=lastYear!==yr?`<h2 class="chronicle-year">${e(yr)}${['日期未知','年份未核'].includes(yr)?'':'年'}</h2>`:'';lastYear=yr;return header+chronicleEntryHTML(row);}).join(''):empty(chronicleFilter==='candidate'?'暂时没有待整理的线索。':'这页个人史，留给真实发生的事。',chronicleFilter==='candidate'?'起居会在交流中继续整理；你也可以补充原话或相关材料。':'继续聊近况，起居会自然记载。完整对话始终保留在“对话原文”。','journal')}</section>`;}
function chronicleSettingsHTML(){return `<section class="card chronicle-settings"><div class="chronicle-settings-identity">${avatarHTML('settings-avatar')}<div><h2>起居 · 个人史秉笔史官</h2><p class="subtle">交流时陪你思考，记载时尊重原话与事实。</p></div></div><form id="chronicle-settings-form"><label for="chronicle-user-title">史官在记载中如何称呼你</label><div class="inline-save"><input name="user_title" id="chronicle-user-title" maxlength="32" required value="${e(chronicleName())}" placeholder="用户"><button type="submit">保存称谓</button></div><p class="form-help">默认“用户”，也可填写自己的名字或其他称谓。起居以第三人称写个人史；称谓设置不改写原话或已有手工正文。</p></form></section>`;}
function chronicleEditModal(row,excluded=false){openModal(excluded?'暂不记载':row.status==='candidate'?'补充个人史线索':'更正个人史记载',`<form id="chronicle-edit-form"><input type="hidden" name="id" value="${e(row.id)}"><input type="hidden" name="excluded" value="${excluded?'true':'false'}"><p class="subtle">${excluded?'这条记载将退出个人史，完整对话和来源仍保留。':'补充遗漏的事实或更正表述。起居会自动形成个人史，你的修改会保留出处与版本。'}</p><label for="chronicle-body">记载正文</label><textarea id="chronicle-body" name="body" required ${excluded?'readonly':''}>${e(row.body||'')}</textarea><div class="chronicle-sources">${chronicleSourcesHTML(row.source_refs||[])}</div><p class="form-help">本次更正保留版本与原始出处。你可以随时再修改；无需逐条批准起居的记载。</p>${formActions(excluded?'暂不记载':'保存更正')}</form>`);}
function monthShift(value,n){const [y,m]=value.slice(0,7).split('-').map(Number),dt=new Date(Date.UTC(y,m-1+n,1));return `${dt.getUTCFullYear()}-${String(dt.getUTCMonth()+1).padStart(2,'0')}-01`;}
function localEventDate(value){if(!value)return '';return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value));}
function localEventInput(value){if(!value)return '';const dt=new Date(value);if(Number.isNaN(dt.valueOf()))return '';const parts=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(dt),get=t=>parts.find(x=>x.type===t)?.value;return `${get('year')}-${get('month')}-${get('day')}T${get('hour')}:${get('minute')}`;}
function calendarNotificationLabel(value){return {none:'未启用提醒',disabled:'未启用提醒',pending:'提醒待发送',sending:'提醒发送中',sent:'通知通道已接受',page_only:'仅网页提示',cancelled:'提醒已取消',completed:'已完成，停止提醒',unknown:'发送结果待核对'}[value]||notificationLabel(value);}
function calendarRows(){return (state.calendar_events||[]).filter(x=>calendarShowCancelled||x.status!=='cancelled');}
function calendarEventHTML(x){return `<article class="calendar-event ${e(x.status)}${routeId===x.id?' linked-event':''}" id="calendar-event-${e(x.id)}"><div class="calendar-event-time">${x.all_day?'全天':e(timeString(x.start_at,false))}<small>${!x.all_day&&x.end_at?e(timeString(x.end_at,false)):''}</small></div><div class="calendar-event-main"><div class="calendar-event-title"><h3>${e(x.title)}</h3><span class="tag ${x.status==='completed'?'good':''}">${{planned:'计划',completed:'本人标记完成',cancelled:'已取消'}[x.status]||'计划'}</span></div>${x.location?`<p class="calendar-location">${e(x.location)}</p>`:''}${x.notes?`<p class="calendar-notes">${e(x.notes)}</p>`:''}<div class="calendar-event-meta">${localEventDate(x.end_at||x.start_at)!==localEventDate(x.start_at)?`<span>${e(localEventDate(x.start_at))} — ${e(localEventDate(x.end_at))}</span>`:''}<span>${x.reminder_minutes===null||x.reminder_minutes===undefined?'不提醒':x.reminder_minutes===0?'开始时提醒':`提前 ${e(x.reminder_minutes)} 分钟提醒`}</span>${x.notification_state?`<span>${e(calendarNotificationLabel(x.notification_state))}</span>`:''}</div></div><div class="calendar-event-actions">${x.status==='planned'?iconButton('编辑日程','edit',`data-action="calendar-edit" data-id="${e(x.id)}"`):''}${x.status==='planned'?iconButton('标记此日程已完成','check',`data-action="calendar-status" data-id="${e(x.id)}" data-status="completed"`)+iconButton('取消此日程','close',`data-action="calendar-status" data-id="${e(x.id)}" data-status="cancelled"`):''}</div></article>`;}
function calendarWeekStart(day){return shifted(day,-((new Date(day+'T12:00:00+08:00').getUTCDay()+6)%7));}
function calendarRange(day=date||state?.today||today(),view=calendarView){
  if(view==='week'){const start=calendarWeekStart(day);return {start,end:shifted(start,6)};}
  if(view==='day')return {start:day,end:day};
  const start=calendarWeekStart(day.slice(0,7)+'-01');return {start,end:shifted(start,41)};
}
function calendarInterval(x){const start=new Date(x.start_at).valueOf(),end=new Date(x.end_at||x.start_at).valueOf();return {start,end};}
function dayEvents(day){
  const start=new Date(day+'T00:00:00+08:00').valueOf(),end=start+86400000;
  return calendarRows().filter(x=>{const t=calendarInterval(x);return t.start<end&&t.end>start;}).sort((a,b)=>new Date(a.start_at)-new Date(b.start_at));
}
function calendarMinuteLabel(minute){const n=Math.max(0,Math.min(1440,Math.round(minute)));return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');}
function calendarSegments(day){
  const midnight=new Date(day+'T00:00:00+08:00').valueOf();
  const rows=dayEvents(day).filter(x=>!x.all_day).map(event=>{
    const t=calendarInterval(event),start=Math.max(0,(t.start-midnight)/60000),end=Math.min(1440,(t.end-midnight)/60000);
    return {event,start,end,visualEnd:Math.min(1440,Math.max(end,start+24)),continuesBefore:t.start<midnight,continuesAfter:t.end>midnight+86400000};
  }).sort((a,b)=>a.start-b.start||b.end-a.end||String(a.event.id).localeCompare(String(b.event.id)));
  // Each connected overlap group gets stable side-by-side lanes, including
  // minimum-height short events. Touching endpoints do not overlap.
  let group=[],ends=[],groupEnd=-1;
  const finish=()=>{for(const item of group)item.lanes=ends.length;group=[];ends=[];groupEnd=-1;};
  for(const item of rows){
    if(group.length&&item.start>=groupEnd)finish();
    let lane=ends.findIndex(end=>end<=item.start);if(lane<0)lane=ends.length;
    item.lane=lane;ends[lane]=item.visualEnd;group.push(item);groupEnd=Math.max(groupEnd,item.visualEnd);
  }
  finish();return rows;
}
function calendarWeekHTML(selected){
  const start=calendarWeekStart(selected),days=Array.from({length:7},(_,i)=>shifted(start,i)),current=state.today||today();
  const allDay=days.map(day=>dayEvents(day).filter(x=>x.all_day));
  return `<p class="calendar-week-hint">上海时间 · 点时间格新建，点日程查看详情。<span>左右滑动可查看整周。</span></p><div class="calendar-week-scroll" tabindex="0" role="region" aria-label="周日程时间轴，可横向与纵向滚动"><div class="calendar-week-inner"><div class="calendar-week-header"><div class="calendar-time-corner">时间</div>${days.map((day,i)=>`<button class="calendar-week-date${day===current?' today':''}${day===selected?' selected':''}" data-action="calendar-day" data-date="${day}" aria-label="查看${day}的日程" aria-pressed="${day===selected}"><span>周${'一二三四五六日'[i]}</span><time datetime="${day}">${Number(day.slice(5,7))}/${Number(day.slice(8))}</time></button>`).join('')}</div><div class="calendar-week-allday"><div class="calendar-allday-label">全天</div>${allDay.map((events,i)=>`<div class="calendar-allday-cell" data-day="${days[i]}">${events.map(x=>`<button class="calendar-allday-event ${e(x.status)}" data-action="calendar-event-open" data-id="${e(x.id)}" title="${e(x.title)}">${e(x.title)}</button>`).join('')||'<span class="calendar-allday-empty" aria-hidden="true">—</span>'}</div>`).join('')}</div><div class="calendar-week-body"><div class="calendar-time-axis" aria-label="00:00至24:00">${Array.from({length:25},(_,h)=>`<span class="calendar-hour-label" data-minute="${h*60}">${String(h).padStart(2,'0')}:00</span>`).join('')}</div>${days.map(day=>`<div class="calendar-week-column${day===current?' today':''}" data-day="${day}" aria-label="${day}的小时日程">${Array.from({length:24},(_,h)=>`<button class="calendar-hour-slot" data-action="calendar-slot" data-date="${day}" data-hour="${h}" aria-label="${day} ${String(h).padStart(2,'0')}:00新建日程"></button>`).join('')}${calendarSegments(day).map(x=>`<button class="calendar-week-event ${e(x.event.status)}${x.continuesBefore?' continues-before':''}${x.continuesAfter?' continues-after':''}" data-action="calendar-event-open" data-id="${e(x.event.id)}" data-start="${x.start}" data-end="${x.visualEnd}" data-lane="${x.lane}" data-lanes="${x.lanes}" aria-label="${e(x.event.title)}，${day} ${calendarMinuteLabel(x.start)}至${calendarMinuteLabel(x.end)}${x.continuesBefore?'，接前一天':''}${x.continuesAfter?'，延续到后一天':''}" title="${e(x.event.title)} · ${calendarMinuteLabel(x.start)}–${calendarMinuteLabel(x.end)}${x.event.location?' · '+e(x.event.location):''}"><span class="calendar-block-time">${x.continuesBefore?'↳ ':''}${calendarMinuteLabel(x.start)}–${calendarMinuteLabel(x.end)}${x.continuesAfter?' ↪':''}</span><strong>${e(x.event.title)}</strong>${x.event.location?`<small>${e(x.event.location)}</small>`:''}</button>`).join('')}</div>`).join('')}</div></div></div>`;
}
function positionCalendarWeek(scroll=null){
  const scroller=$('.calendar-week-scroll');if(!scroller)return;
  // Only bounded numbers reach CSSOM; no style attribute is interpolated from
  // data and the existing style-src 'self' policy remains unchanged.
  $$('.calendar-hour-label').forEach(x=>x.style.top=Number(x.dataset.minute)+'px');
  $$('.calendar-week-event').forEach(x=>{const start=Number(x.dataset.start),end=Number(x.dataset.end),lane=Number(x.dataset.lane),lanes=Number(x.dataset.lanes);x.style.top=start+'px';x.style.height=Math.max(1,end-start)+'px';x.style.left=`calc(${lane*100/lanes}% + 2px)`;x.style.width=`calc(${100/lanes}% - 4px)`;});
  if(scroll){scroller.scrollTop=scroll.top;scroller.scrollLeft=scroll.left;}else scroller.scrollTop=8*60;
}
function locateCalendarToday(){
  const scroller=$('.calendar-week-scroll'),column=$('.calendar-week-column.today');if(!scroller||!column)return;
  const parts=localEventInput(new Date().toISOString()).slice(11).split(':').map(Number),minutes=parts[0]*60+parts[1];
  scroller.scrollTop=Math.max(0,minutes-120);
  scroller.scrollLeft=Math.max(0,column.offsetLeft-58-(scroller.clientWidth-column.clientWidth)/2);
}
function calendarEventModal(x){
  openModal('日程详情',`<div class="calendar-detail">${calendarEventHTML(x).replace(`id="calendar-event-${e(x.id)}"`,'')}<p class="form-help">上海时间 · ${e(localEventInput(x.start_at).replace('T',' '))} — ${e(localEventInput(x.end_at).replace('T',' '))}</p></div>`);
}
function renderCalendar(){
  const previous=$('.calendar-week-scroll'),saved=previous?{top:previous.scrollTop,left:previous.scrollLeft}:null;
  const selected=date||state.today||today(),month=selected.slice(0,7),range=calendarRange(selected,'month'),days=Array.from({length:42},(_,i)=>shifted(range.start,i)),events=dayEvents(selected),week=calendarRange(selected,'week');
  const caption=calendarView==='week'?(week.start.slice(0,4)!==week.end.slice(0,4)?`${week.start.replaceAll('-','/')} — ${week.end.replaceAll('-','/')}`:`${week.start.slice(5).replace('-','/')} — ${week.end.slice(5).replace('-','/')} · ${week.start.slice(0,4)}`):calendarView==='day'?selected:month.replace('-','年')+'月';
  const unit=calendarView==='week'?'周':calendarView==='day'?'天':'个月';
  $('#page').innerHTML=`${heading('日程安排','留出专注，也给生活留一点余地。',`<button class="icon-button calendar-new" data-action="calendar-new" aria-label="新建日程" title="新建日程">${icon('plus')}</button>`,'CALENDAR / 日程')}<section class="calendar-surface"><div class="calendar-toolbar"><div class="calendar-month-navigation">${iconButton('上一'+unit,'chevron','data-action="calendar-period" data-offset="-1"','ghost previous')}<h2>${e(caption)}</h2>${iconButton('下一'+unit,'chevron','data-action="calendar-period" data-offset="1"')}<button class="small ghost" data-action="calendar-today">今天</button></div><div class="segmented" role="group" aria-label="日历视图">${[['month','月历'],['week','周视图'],['day','日列表']].map(([key,label])=>`<button class="${calendarView===key?'selected':''}" data-action="calendar-view" data-view="${key}" aria-pressed="${calendarView===key}">${label}</button>`).join('')}</div></div>${calendarView==='week'?calendarWeekHTML(selected):calendarView==='month'?`<div class="calendar-weekdays" aria-hidden="true">${[...'一二三四五六日'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid" aria-label="${e(month)}月日历">${days.map(day=>{const entries=dayEvents(day),inMonth=day.startsWith(month);return `<button class="calendar-day${inMonth?'':' other-month'}${day===selected?' selected':''}${day===(state.today||today())?' today':''}" data-action="calendar-day" data-date="${day}" aria-label="${day}，${entries.length}项日程" aria-pressed="${day===selected}"><time datetime="${day}">${Number(day.slice(8))}</time><div class="calendar-day-events">${entries.slice(0,2).map(x=>`<span class="calendar-mini-event ${e(x.status)}">${e(x.title)}</span>`).join('')}${entries.length>2?`<small>另 ${entries.length-2} 项</small>`:''}</div>${entries.length?`<span class="calendar-mobile-dots" aria-hidden="true">${entries.slice(0,3).map(x=>`<i class="${e(x.status)}"></i>`).join('')}</span>`:''}</button>`;}).join('')}</div>`:''}<div class="calendar-day-heading"><div class="calendar-selected-date"><h2>${e(selected)} <small>${selected===(state.today||today())?'今天':''}</small></h2><form id="calendar-date-form"><input type="date" name="date" value="${e(selected)}" aria-label="选择日程日期"><button type="submit" class="icon-button" title="查看此日期" aria-label="查看此日期">${icon('arrow')}</button></form></div><label class="check-row"><input type="checkbox" id="calendar-show-cancelled" ${calendarShowCancelled?'checked':''}>显示已取消</label></div><div class="calendar-day-list">${events.length?events.map(calendarEventHTML).join(''):empty('这一天，还没有安排。','可以留白，也可以记下一件想做的事。','calendar')}</div><p class="calendar-footnote">上海时间 · 每日学习、反思与打卡仍在各自项目中，沿用原有每日安排。</p></section>`;
  $('#calendar-show-cancelled').addEventListener('change',event=>{calendarShowCancelled=event.target.checked;renderCalendar();});
  positionCalendarWeek(saved);
}

function calendarModal(event=null,slot=null){const selected=slot?.day||date||state.today||today(),x=event||{},start=x.start_at?localEventInput(x.start_at):selected+'T'+String(slot?.hour??9).padStart(2,'0')+':00',end=x.end_at?localEventInput(x.end_at):slot?.hour===23?shifted(selected,1)+'T00:00':selected+'T'+String((slot?.hour??9)+1).padStart(2,'0')+':00';openModal(event?'编辑日程':'新建日程',`<form id="calendar-event-form"><input type="hidden" name="event_id" value="${e(x.id||'')}"><input type="hidden" name="expected_version" value="${e(x.version||'')}"><input type="hidden" name="submission_id" value="${e(uid())}"><label for="calendar-title">日程名称</label><input name="title" id="calendar-title" value="${e(x.title||'')}" maxlength="200" required placeholder="例如：实验讨论、读书、与朋友见面"><label class="check-row"><input id="calendar-all-day" name="all_day" type="checkbox" ${x.all_day?'checked':''}>全天</label><div class="two-col"><div><label for="calendar-start">开始（上海时间）</label><input id="calendar-start" name="start_at" type="${x.all_day?'date':'datetime-local'}" value="${e(x.all_day?start.slice(0,10):start)}" required></div><div><label for="calendar-end">结束（上海时间）</label><input id="calendar-end" name="end_at" type="${x.all_day?'date':'datetime-local'}" value="${e(x.all_day?end.slice(0,10):end)}" required></div></div><label for="calendar-location">地点或会议入口（可选）</label><input name="location" id="calendar-location" value="${e(x.location||'')}" maxlength="500" placeholder="地点、房间号或会议链接"><label for="calendar-notes">备注（可选）</label><textarea id="calendar-notes" name="notes" maxlength="5000">${e(x.notes||'')}</textarea><label for="calendar-reminder">手机提醒</label><select id="calendar-reminder" name="reminder_minutes">${[['','不提醒'],['0','开始时'],['5','提前5分钟'],['15','提前15分钟'],['30','提前30分钟'],['60','提前1小时'],['1440','提前1天'],...(x.reminder_minutes!=null&&![0,5,15,30,60,1440].includes(x.reminder_minutes)?[[String(x.reminder_minutes),`提前${x.reminder_minutes}分钟`]]:[])].map(([v,label])=>`<option value="${v}" ${String(x.reminder_minutes??'')===v?'selected':''}>${label}</option>`).join('')}</select><p class="form-help">选择提醒后通过已有私网通知发送；通知正文不包含具体私事。保存的是计划，不表示事情已经发生。每日例程在设置中单独调整。</p>${formActions(event?'保存修改':'保存日程')}</form>`);}
function toggleCalendarAllDay(){const allDay=$('#calendar-all-day').checked;for(const id of ['calendar-start','calendar-end']){const input=$('#'+id),value=input.value;input.type=allDay?'date':'datetime-local';input.value=allDay?value.slice(0,10):value.slice(0,10)+(id==='calendar-start'?'T09:00':'T10:00');}}
function materialGuidesHTML(){return `<section class="material-guides"><div><h2>让各平台整理文件，起居统一归档</h2><p>GPT、Kimi 可各自生成一份材料文件。整批预览与导入后，起居依据原话自动整理个人史。</p></div><div class="material-guide-actions"><button data-action="material-guide" data-source="kimi">Kimi 准备指南 ${icon('arrow')}</button><button data-action="material-guide" data-source="chatgpt">ChatGPT 准备指南 ${icon('arrow')}</button></div></section>`;}
function materialGuide(source){const chatgpt=source==='chatgpt',name=chatgpt?'ChatGPT':'Kimi';openModal(`${name} 材料准备`, `<div class="material-guide-body"><p class="subtle">一次整理多段或多份相关会话，按文件批量准备；只保留你愿意交给起居的内容。</p><ol><li><strong>批量整理并保留来源。</strong>打开下面的 ${name} 材料指令，将它复制到相应平台，整理你能提供的历史会话。可按会话或主题合成文件，每个文件不超过8 MB；不必逐段发送到起居。已有导出文件时，直接以导出为基础。</li><li><strong>原话、来源说明、史稿分开。</strong>用户原话逐字保留，必要助手上下文独立标注；会话标题、已知日期与来源说明单列。助手整理的个人史稿要独立标注，起居结合原话与来源自动形成记载；不能把助手建议冒充用户原话或已发生事实，未知日期留空。</li><li><strong>记忆和项目规则另存。</strong>Memory、AGENTS 等内容使用对应资料类型与作用域，不混入普通会话。先移除密钥及不准备保存的第三方信息。</li><li><strong>导入前预览整个文件。</strong>回到资料页选择来源与文件，点击“预览导入”；选择全部所需用户原话及必要助手上下文，再“重新预览所选”。多个文件可依次导入。</li><li><strong>导入后由起居整理个人史。</strong>检查日期、重复项、失败与缺失附件，再“导入所选记录”。原话保留在“对话原文”，来源充分的史事自然进入个人史；你可以随时更正或选择暂不记载，无需逐条批准。</li></ol><p class="form-help">起居读取的是你选择的本地文件；没有连接你的 ${name} 账号，也不会宣称尚未导入的资料已收到。材料准备指令须由你在相应平台使用。</p><div class="guide-downloads"><a href="/guide/${chatgpt?'chatgpt':'kimi'}-material-instructions" target="_blank" rel="noopener noreferrer">${name} 批量材料指令</a><a href="/guide/material-batch-example" target="_blank" rel="noopener noreferrer">批量格式示例</a><a href="/guide/material-template" target="_blank" rel="noopener noreferrer">空白材料模板</a><a href="/guide/materials" target="_blank" rel="noopener noreferrer">完整准备说明</a></div><div class="form-actions"><button data-action="material-guide-use" data-source="${source}" class="primary">使用此来源准备导入</button></div></div>`);}
function selectedImportIds(){return $$('input[name="import-message"]:checked').map(x=>x.value).sort();}
function sameSelection(a,b){return JSON.stringify([...(a||[])].sort())===JSON.stringify([...(b||[])].sort());}
function updateImportSelection(){if(!preview)return;const selected=selectedImportIds(),valid=preview.selectionConfirmed&&sameSelection(selected,preview.params.selected_message_ids);const label=$('#import-selection-count');if(label)label.textContent=`已选 ${selected.length} 条`;const apply=$('[data-action="import-apply"]');if(apply)apply.disabled=!valid||!selected.length;const next=$('[data-action="import-selection-preview"]');if(next)next.disabled=!selected.length;const notice=$('#import-selection-notice');if(notice)notice.textContent=valid?'所选内容已重新预览，可以核对后导入。':'勾选后请重新预览所选内容；未应用前不会写入资料库。';}
function importPreviewHTML(result,allItems,selected=[],confirmed=false){const items=allItems||result.items||[];return `<div class="notice info"><strong>${e(preview.params.filename)}</strong><br>本次预览：总计 ${e(result.counts?.total??result.count??0)} · 新增 ${e(result.counts?.new??0)} · 重复 ${e(result.counts?.duplicates??result.duplicates??0)} · 删除账本过滤 ${e(result.counts?.deleted??0)}<br>日期范围：${e((result.date_range||result.range||[]).join(' — '))||'来源未提供'}<br>失败 ${(result.failures||[]).length} · 缺失附件 ${(result.missing_attachments||[]).length}</div>${(result.failures||[]).length?`<details><summary>查看失败项</summary><pre class="code-text">${e(readable(result.failures))}</pre></details>`:''}${(result.warnings||[]).length?`<p class="subtle">${e(readable(result.warnings))}</p>`:''}${(result.missing_attachments||[]).length?`<details><summary>缺失附件</summary><pre class="code-text">${e(readable(result.missing_attachments))}</pre></details>`:''}<section class="import-selection"><div class="section-heading"><h3>选择要保留的原话</h3><span id="import-selection-count" class="small muted">已选 ${selected.length} 条</span></div><div class="import-selection-tools"><button type="button" class="small ghost" data-action="import-select" data-mode="user">选择用户原话</button><button type="button" class="small ghost" data-action="import-select" data-mode="all">全选</button><button type="button" class="small ghost" data-action="import-select" data-mode="none">清空</button></div><div class="import-items">${items.length?items.map(m=>`<label class="import-item"><input type="checkbox" name="import-message" value="${e(m.message_id)}" data-role="${e(m.role)}" ${selected.includes(m.message_id)?'checked':''}><span><strong>${e(m.title||m.conversation_id||'来源记录')}</strong><small>${e(m.role==='user'?'用户原话':m.role==='assistant'?'助手上下文':m.role||'来源材料')} · ${m.original_at?e(timeString(m.original_at)):'原日期未知'}</small><span class="import-item-body">${e(m.body||'')}</span></span></label>`).join(''):'<p class="subtle">没有可选择的来源记录，请核对文件格式或失败清单。</p>'}</div><p id="import-selection-notice" class="form-help">${confirmed?'所选内容已重新预览，可以核对后导入。':'尚未导入；请勾选所需记录，再重新预览。'}</p><div class="form-actions"><button type="button" data-action="import-selection-preview" ${!selected.length?'disabled':''}>重新预览所选</button><button type="button" class="primary" data-action="import-apply" ${!confirmed||!selected.length?'disabled':''}>导入所选记录</button></div></section>`;}
async function handleChronicleAction(el){const type=el.dataset.action;switch(type){case 'learning-history-open':{const items=(state.routine_projects||[]).find(p=>p.routine==='A1')?.historical_deliveries||[];const item=items.find(x=>x.id===el.dataset.id);if(item)historicalDeliveryModal(item);return true;}case 'chronicle-filter':chronicleFilter=el.dataset.filter;renderChronicle();return true;case 'chronicle-edit':case 'chronicle-exclude':{const row=chronicleRows().find(x=>x.id===el.dataset.id);if(!row?.activity_id&&!row?.import_id&&!row?.compiled_profile_id)throw Error('请先核对来源材料。');chronicleEditModal(row,type==='chronicle-exclude');return true;}case 'calendar-new':calendarModal();return true;case 'calendar-slot':calendarModal(null,{day:el.dataset.date,hour:Number(el.dataset.hour)});return true;case 'calendar-event-open':{const x=(state.calendar_events||[]).find(x=>x.id===el.dataset.id);if(x)calendarEventModal(x);return true;}case 'calendar-edit':{const x=(state.calendar_events||[]).find(x=>x.id===el.dataset.id);if(x)calendarModal(x);return true;}case 'calendar-status':{const x=(state.calendar_events||[]).find(x=>x.id===el.dataset.id);if(!x)return true;const completed=el.dataset.status==='completed';openModal(completed?'标记日程已完成':'取消日程',`<form id="calendar-status-form"><input type="hidden" name="event_id" value="${e(x.id)}"><input type="hidden" name="expected_version" value="${e(x.version)}"><input type="hidden" name="status" value="${completed?'completed':'cancelled'}"><p>${e(x.title)}</p><p class="subtle">${completed?'请仅在这件事确实完成后确认。该状态由你本人明确记录。':'取消会停止这项日程的后续提醒，保留已有计划记录。'}</p>${formActions(completed?'确认已完成':'确认取消日程')}</form>`);return true;}case 'calendar-view':calendarView=['month','week','day'].includes(el.dataset.view)?el.dataset.view:'month';await refreshState();if(route==='calendar')renderCalendar();return true;case 'calendar-period':{const n=Number(el.dataset.offset);date=calendarView==='month'?monthShift(date||today(),n):shifted(date||today(),n*(calendarView==='week'?7:1));await refreshState();if(route==='calendar')renderCalendar();return true;}case 'calendar-month':date=monthShift(date||today(),Number(el.dataset.offset));await refreshState();if(route==='calendar')renderCalendar();return true;case 'calendar-day':date=el.dataset.date;await refreshState();if(route==='calendar')renderCalendar();return true;case 'calendar-today':date=state.today||today();await refreshState();if(route==='calendar'){renderCalendar();locateCalendarToday();}return true;case 'material-guide':materialGuide(el.dataset.source);return true;case 'material-guide-use':closeModal();$('#import-source').value=el.dataset.source;$('#import-file').focus();return true;case 'import-select':$$('input[name="import-message"]').forEach(x=>x.checked=el.dataset.mode==='all'||el.dataset.mode==='user'&&x.dataset.role==='user');updateImportSelection();return true;case 'import-selection-preview':{if(!preview)throw Error('请先选择文件并预览。');const selected=selectedImportIds();if(!selected.length)throw Error('请至少选择一条来源记录。');el.disabled=true;const params={...preview.params,selected_message_ids:selected},result=await action('import_preview',params);preview={params,result,allItems:preview.allItems,selectionConfirmed:true};$('#import-preview').innerHTML=importPreviewHTML(result,preview.allItems,selected,true);return true;}case 'import-apply':{if(!preview?.selectionConfirmed||!sameSelection(selectedImportIds(),preview.params.selected_message_ids))throw Error('选择已改变，请先重新预览所选内容。');el.disabled=true;const result=await action('import_apply',{...preview.params,preview_token:preview.result.preview_token});toast(`所选记录已导入：${result.counts?.new??result.count??0} 条新增。`);preview=null;await loadRoute();return true;}}return false;}
async function handleChronicleForm(form){const fd=new FormData(form),get=k=>String(fd.get(k)||'');switch(form.getAttribute('id')){case 'chronicle-filter-form':chronicleQuery=get('q');chronicleYear=get('year');renderChronicle();return true;case 'chronicle-settings-form':await action('chronicle_settings',{user_title:get('user_title').trim()});await refreshState();if(route==='settings')renderSettings();toast('记载称谓已保存，原话保持不变。');return true;case 'chronicle-edit-form':{const row=chronicleRows().find(x=>x.id===get('id'));if(!row?.activity_id&&!row?.import_id&&!row?.compiled_profile_id)throw Error('这条来源需先核对。');await action(row.compiled_profile_id?'chronicle_compiled_revise':row.import_id?'chronicle_import_revise':'chronicle_revise',{...(row.compiled_profile_id?{profile_id:row.compiled_profile_id}:row.import_id?{message_id:row.import_id}:{activity_id:row.activity_id,source_ids:row.source_ids||[]}),body:get('body'),expected_version:row.correction_version??0,excluded:get('excluded')==='true'});closeModal();await refreshState();if(route==='journal')renderChronicle();toast(get('excluded')==='true'?'已退出个人史，原话仍保留。':'个人史更正已保存。');return true;}case 'calendar-date-form':date=get('date')||today();await refreshState();if(route==='calendar')renderCalendar();return true;case 'calendar-event-form':{const allDay=fd.has('all_day'),start=get('start_at')+(allDay?'T00:00:00+08:00':':00+08:00'),end=get('end_at')+(allDay?'T23:59:59+08:00':':00+08:00');if(new Date(end)<=new Date(start))throw Error('结束时间须晚于开始时间。');await action('calendar_save',{...(get('event_id')?{event_id:get('event_id'),expected_version:Number(get('expected_version'))}:{submission_id:get('submission_id')}),title:get('title').trim(),start_at:start,end_at:end,all_day:allDay,location:get('location'),notes:get('notes'),reminder_minutes:get('reminder_minutes')===''?null:Number(get('reminder_minutes'))});date=get('start_at').slice(0,10);closeModal();await refreshState();if(route==='calendar')renderCalendar();toast('日程已保存，状态仍按实际计划记录。');return true;}case 'calendar-status-form':await action('calendar_status',{event_id:get('event_id'),expected_version:Number(get('expected_version')),status:get('status')});closeModal();await refreshState();if(route==='calendar')renderCalendar();toast(get('status')==='completed'?'已记录本人确认完成。':'日程已取消。');return true;case 'import-form':{const file=$('#import-file').files[0];if(!file)throw Error('请先选择历史资料文件。');if(file.size>8_000_000)throw Error('单个文件上限8 MB，请按来源会话拆分。');const params={source:get('source'),channel:get('source'),kind:get('kind'),scope:get('scope'),filename:file.name,content:await file.text()};if(params.kind==='instructions'&&!params.scope.startsWith('project:'))throw Error('项目规则的作用域需要以 project: 开头。');const result=await action('import_preview',params);preview={params,result,allItems:result.items||[],selectionConfirmed:false};$('#import-preview').innerHTML=importPreviewHTML(result,preview.allItems);return true;}}return false;}

bootstrap();
